135	inline static int64_t Align(const int64_t elementNum, const int64_t bytes)
136	{
137	    if (bytes == 0) {
138	        return 0;
139	    }
140	    return (elementNum * bytes + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE / bytes;
141	}
142	
143	inline static int64_t AlignBytes(const int64_t elementNum, const int64_t bytes)
144	{
145	    return (elementNum * bytes + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
146	}
