336	ge::graphStatus MoeInitRountingV3TilingBase::CheckAttr()
337	{
338	    quantMode_ = *quantModePtr_;
339	    moeInitRoutingV3TilingData.set_quantMode(quantMode_);
340	    OP_LOGI(context_, "quant_mode is: %ld ", quantMode_);
341	
342	    dropPadMode_ = *dropPadModePtr_;
343	    moeInitRoutingV3TilingData.set_dropPadMode(dropPadMode_);
344	    OP_CHECK_IF(
345	        (dropPadMode_ != DROP_LESS) && (dropPadMode_ != DROP_PAD),
346	        OP_LOGE(context_, "drop_pad_mode should be %ld or %ld", DROP_LESS, DROP_PAD), return ge::GRAPH_FAILED);
347	
348	    rowIdxTytpe_ = *rowIdxTypePtr_;
349	    moeInitRoutingV3TilingData.set_rowIdxType(rowIdxTytpe_);
350	    OP_LOGI(context_, "row_idx_type is: %ld ", rowIdxTytpe_);
351	
352	    activeNum_ = *activeNumPtr_;
353	    if (dropPadMode_ == DROP_LESS) {
354	        OP_CHECK_IF(
355	            activeNum_ < ACTIVE_NUM_MIN_VALUE,
356	            OP_LOGE(context_, "active_num should be greater than or equal to %ld", ACTIVE_NUM_MIN_VALUE),
357	            return ge::GRAPH_FAILED);
358	    }
359	
360	    expertNum_ = *expertNumPtr_;
361	    moeInitRoutingV3TilingData.set_expertNum(expertNum_);
362	    OP_CHECK_IF(expertNum_ <= 0, OP_LOGE(context_, "expert_num should be greater than 0"), return ge::GRAPH_FAILED);
363	    OP_CHECK_IF(
364	        activeExpertRangeListPtr_->GetSize() != ATTR_EXPERT_RANGE_DIM && activeExpertRangeListPtr_->GetSize() != 0,
365	        OP_LOGE(context_, "The dim number of expert_range should be %ld or 0(no input)", ATTR_EXPERT_RANGE_DIM),
366	        return ge::GRAPH_FAILED);
367	    if (activeExpertRangeListPtr_->GetSize() == 0) {
368	        expertStart_ = 0;
369	        expertEnd_ = expertNum_;
370	    } else {
371	        const int64_t* expertRangeList = reinterpret_cast<const int64_t*>(activeExpertRangeListPtr_->GetData());
372	        expertStart_ = expertRangeList[0];
373	        expertEnd_ = expertRangeList[1];
374	    }
375	    moeInitRoutingV3TilingData.set_expertStart(expertStart_);
376	    moeInitRoutingV3TilingData.set_expertEnd(expertEnd_);
377	    moeInitRoutingV3TilingData.set_actualExpertNum(expertEnd_ - expertStart_);
378	    OP_LOGI(
379	        context_, "expert_start is: %ld, expert_end is: %ld, actualExpertNum is: %ld ", expertStart_, expertEnd_,
380	        expertEnd_ - expertStart_);
381	
382	    n_ = xShapePtr_->GetStorageShape().GetDim(0);
383	    expertCapacity_ = *expertCapacityPtr_;
384	    moeInitRoutingV3TilingData.set_expertCapacity(expertCapacity_);
385	    if (dropPadMode_ == DROP_PAD) {
386	        OP_CHECK_IF(
387	            expertCapacity_ <= EXPERT_CAPACITY_MIN_VALUE || expertCapacity_ > n_,
388	            OP_LOGE(context_, "expert_Capacity should be greater than 0 and less than %ld", n_),
389	            return ge::GRAPH_FAILED);
390	        OP_CHECK_IF(
391	            rowIdxTytpe_ == SCATTER, OP_LOGE(context_, "rowIdxTytpe should be 0 when droppadmode is 1"),
392	            return ge::GRAPH_FAILED);
393	        OP_CHECK_IF(
394	            expertStart_ != 0 || expertEnd_ != expertNum_,
395	            OP_LOGE(context_, "expert_range should be [0, %ld] when droppadmode is 1", expertNum_),
396	            return ge::GRAPH_FAILED);
397	    }
398	
399	    expertTokensNumType_ = *expertTokensNumTypePtr_;
400	    moeInitRoutingV3TilingData.set_expertTokensNumType(expertTokensNumType_);
401	    OP_CHECK_IF(
402	        (expertTokensNumType_ != COUNT) && (expertTokensNumType_ != KEY_VALUE) && (expertTokensNumType_ != CUMSUM),
403	        OP_LOGE(context_, "expert_tokens_num_type currently not support %ld", expertTokensNumType_),
404	        return ge::GRAPH_FAILED);
405	
406	    expertTokensNumFlag_ = *expertTokensNumFlagPtr_;
407	    if (dropPadMode_ == DROP_PAD && expertTokensNumFlag_) {
408	        OP_CHECK_IF(
409	            expertTokensNumType_ != COUNT,
410	            OP_LOGE(
411	                context_,
412	                "In DROP_PAD mode and expert_tokens_num_flag is true, expert_tokens_num_type only supports COUNT,but "
413	                "got %ld",
414	                expertTokensNumType_),
415	            return ge::GRAPH_FAILED);
416	    }
417	    if (expertTokensNumFlag_) {
418	        moeInitRoutingV3TilingData.set_expertTokensNumFlag(1);
419	    } else {
420	        moeInitRoutingV3TilingData.set_expertTokensNumFlag(0);
421	    }
422	
423	    OP_CHECK_IF(
424	        expertStart_ < 0, OP_LOGE(context_, "expert_start should be greater than or equal to 0"),
425	        return ge::GRAPH_FAILED);
426	    OP_CHECK_IF(
427	        expertStart_ >= expertEnd_, OP_LOGE(context_, "expert_start should be less than expert_end"),
428	        return ge::GRAPH_FAILED);
429	    OP_CHECK_IF(
430	        expertEnd_ > expertNum_, OP_LOGE(context_, "expert_end should be less than or equal to %ld", expertNum_),
431	        return ge::GRAPH_FAILED);
432	    if (expertTokensNumType_ == KEY_VALUE) {
433	        OP_CHECK_IF(
434	            expertEnd_ > KV_MODE_EXPERT_IDX_MAX,
435	            OP_LOGE(
436	                context_, "expert_end should be less than or equal to %ld in KEY_VALUE mode", KV_MODE_EXPERT_IDX_MAX),
437	            return ge::GRAPH_FAILED);
438	    } else {
439	        OP_CHECK_IF(
440	            expertEnd_ > EXPERT_IDX_MAX,
441	            OP_LOGE(context_, "expert_end should be less than or equal to %ld", EXPERT_IDX_MAX),
442	            return ge::GRAPH_FAILED);
443	    }
444	    OP_CHECK_IF(
445	        quantMode_ != UN_QUANT && quantMode_ != DYNAMIC_QUANT && quantMode_ != STATIC_QUANT,
446	        OP_LOGE(context_, "quant_mode currently support %ld, %ld or %ld", UN_QUANT, DYNAMIC_QUANT, STATIC_QUANT),
447	        return ge::GRAPH_FAILED);
448	    OP_CHECK_IF(
449	        rowIdxTytpe_ != SCATTER && rowIdxTytpe_ != GATHER,
450	        OP_LOGE(context_, "row_idx_type currently support %ld or %ld", SCATTER, GATHER), return ge::GRAPH_FAILED);
451	    return ge::GRAPH_SUCCESS;
452	}
