454	ge::graphStatus MoeInitRountingV3TilingBase::CheckInputShape()
455	{
456	    const gert::Shape xShape = xShapePtr_->GetStorageShape();
457	    OP_LOGI(context_, "input x shape: %s ", OpsBaseToString(xShape).c_str());
458	    const gert::Shape expertIdxShape = expertIdxShapePtr_->GetStorageShape();
459	    OP_LOGI(context_, "input expert_idx shape: %s.", OpsBaseToString(expertIdxShape).c_str());
460	
461	    // 参数校验
462	    OP_CHECK_IF(
463	        xShape.GetDimNum() != DIM_TWO, OP_LOGE(context_, "The dim number of x should be %lu.", DIM_TWO),
464	        return ge::GRAPH_FAILED);
465	    OP_CHECK_IF(
466	        expertIdxShape.GetDimNum() != DIM_TWO,
467	        OP_LOGE(context_, "The dim number of expert_idx should be %lu.", DIM_TWO), return ge::GRAPH_FAILED);
468	    OP_CHECK_IF(
469	        xShape.GetDim(0) != expertIdxShape.GetDim(0), OP_LOGE(context_, "Input rows should be same."),
470	        return ge::GRAPH_FAILED);
471	
472	    n_ = expertIdxShape.GetDim(0);
473	    k_ = expertIdxShape.GetDim(1);
474	    cols_ = xShape.GetDim(1);
475	    moeInitRoutingV3TilingData.set_n(n_);
476	    moeInitRoutingV3TilingData.set_k(k_);
477	    moeInitRoutingV3TilingData.set_cols(cols_);
478	    totalLength_ = n_ * k_;
479	
480	    // 空tensor场景
481	    if (n_ == 0) {
482	        isEmptyTensor_ = true;
483	        int64_t expertCountElements = 0;
484	        if (expertTokensNumType_ == KEY_VALUE) {
485	            expertCountElements = expertNum_ * KEY_VALUE_MODE_DIM0_NUM;
486	        } else {
487	            expertCountElements = expertEnd_ - expertStart_;
488	        }
489	        moeInitRoutingV3TilingData.set_expertCountElements(expertCountElements);
490	    }
491	
492	    if (activeNum_ == 0 || activeNum_ == ACTIVE_NUM_MIN_VALUE) {
493	        activeNum_ = totalLength_;
494	    } else {
495	        activeNum_ = std::min(activeNum_, totalLength_);
496	    }
497	    moeInitRoutingV3TilingData.set_activeNum(activeNum_);
498	
499	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputDesc(INPUT_X_INDEX));
500	    inuptXDtypeSize_ =
501	        static_cast<int64_t>(ge::GetSizeByDataType(context_->GetInputDesc(INPUT_X_INDEX)->GetDataType()));
502	    OP_LOGI(context_, "Input x dtype size is: %ld. ", inuptXDtypeSize_);
503	
504	    if (quantMode_ == UN_QUANT && scaleShapePtr_ != nullptr) {
505	        auto scaleShape = scaleShapePtr_->GetStorageShape();
506	        OP_LOGI(context_, "input scale shape: %s", OpsBaseToString(scaleShape).c_str());
507	        auto scaleDimNum = static_cast<int64_t>(scaleShape.GetDimNum());
508	        OP_CHECK_IF(
509	            scaleDimNum != 1, OP_LOGE(context_, "The dim number of scale should be 1, current is %ld", scaleDimNum),
510	            return ge::GRAPH_FAILED);
511	        auto scaleDim0 = static_cast<int64_t>(scaleShape.GetDim(0));
512	        OP_CHECK_IF(
513	            scaleDim0 != n_, OP_LOGE(context_, "The first dim of scale should be n_, current is %ld", scaleDim0),
514	            return ge::GRAPH_FAILED);
515	    }
516	
517	    if (quantMode_ == STATIC_QUANT) {
518	        OP_CHECK_IF(scaleShapePtr_ == nullptr, OP_LOGE(context_, "scale is null"), return ge::GRAPH_FAILED);
519	        OP_CHECK_IF(offsetShapePtr_ == nullptr, OP_LOGE(context_, "offset is null"), return ge::GRAPH_FAILED);
520	        auto scaleShape = scaleShapePtr_->GetStorageShape();
521	        OP_LOGI(context_, "input scale shape: %s", OpsBaseToString(scaleShape).c_str());
522	        auto scaleDimNum = static_cast<int64_t>(scaleShape.GetDimNum());
523	        OP_CHECK_IF(
524	            scaleDimNum != 1, OP_LOGE(context_, "The dim number of scale should be 1, current is %ld", scaleDimNum),
525	            return ge::GRAPH_FAILED);
526	        auto scaleDim0 = static_cast<int64_t>(scaleShape.GetDim(0));
527	        OP_CHECK_IF(
528	            scaleDim0 != 1, OP_LOGE(context_, "The first dim of scale should be 1, current is %ld", scaleDim0),
529	            return ge::GRAPH_FAILED);
530	        auto offsetShape = offsetShapePtr_->GetStorageShape();
531	        OP_LOGI(context_, "input offset shape: %s", OpsBaseToString(offsetShape).c_str());
532	        auto offsetDimNum = static_cast<int64_t>(offsetShape.GetDimNum());
533	        OP_CHECK_IF(
534	            offsetDimNum != 1, OP_LOGE(context_, "The dim number of offset should be 1, current is %ld", offsetDimNum),
535	            return ge::GRAPH_FAILED);
536	        auto offsetDim0 = static_cast<int64_t>(offsetShape.GetDim(0));
537	        OP_CHECK_IF(
538	            offsetDim0 != 1, OP_LOGE(context_, "The first dim of offset should be 1, current is %ld", offsetDim0),
539	            return ge::GRAPH_FAILED);
540	    }
541	
542	    if (quantMode_ == DYNAMIC_QUANT && scaleShapePtr_ != nullptr) {
543	        auto scaleShape = scaleShapePtr_->GetStorageShape();
544	        OP_LOGI(context_, "input scale shape: %s", OpsBaseToString(scaleShape).c_str());
545	        auto scaleDimNum = static_cast<int64_t>(scaleShape.GetDimNum());
546	        OP_CHECK_IF(
547	            scaleDimNum != NUM_TWO,
548	            OP_LOGE(context_, "The dim number of scale should be 2, current is %ld", scaleDimNum),
549	            return ge::GRAPH_FAILED);
550	        auto scaleDim0 = static_cast<int64_t>(scaleShape.GetDim(0));
551	        OP_CHECK_IF(
552	            scaleDim0 != (expertEnd_ - expertStart_) && scaleDim0 != 1,
553	            OP_LOGE(
554	                context_, "The first dim of scale should be %ld or 1, current is %ld", (expertEnd_ - expertStart_),
555	                scaleDim0),
556	            return ge::GRAPH_FAILED);
557	        auto scaleDim1 = static_cast<int64_t>(scaleShape.GetDim(1));
558	        OP_CHECK_IF(
559	            scaleDim1 != cols_,
560	            OP_LOGE(context_, "The second dim of scale should be %ld, current is %ld", cols_, scaleDim0),
561	            return ge::GRAPH_FAILED);
562	        if (scaleDim0 == 1) {
563	            smoothType_ = scale1H;
564	        } else {
565	            smoothType_ = scaleEH;
566	        }
567	        moeInitRoutingV3TilingData.set_smoothType(smoothType_);
568	    }
569	    return ge::GRAPH_SUCCESS;
570	}
