572	ge::graphStatus MoeInitRountingV3TilingBase::CheckOutShape()
573	{
574	    // 获取输入shape
575	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputShape(0));
576	    const gert::Shape expandedXShape = context_->GetOutputShape(0)->GetStorageShape();
577	    OP_LOGI(context_, "expanded_x shape: %s.", OpsBaseToString(expandedXShape).c_str());
578	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputShape(1));
579	    const gert::Shape expandedRowIdxShape = context_->GetOutputShape(1)->GetStorageShape();
580	    OP_LOGI(context_, "expanded_row_idx shape: %s.", OpsBaseToString(expandedRowIdxShape).c_str());
581	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputShape(NUM_TWO));
582	    const gert::Shape expertTokensCountOrCumsumShape = context_->GetOutputShape(NUM_TWO)->GetStorageShape();
583	    OP_LOGI(
584	        context_, "expert_tokens_count_or_cumsum shape: %s.", OpsBaseToString(expertTokensCountOrCumsumShape).c_str());
585	
586	    size_t expandedXDimNum = expandedXShape.GetDimNum();
587	    if (dropPadMode_ > 0) {
588	        OP_CHECK_IF(
589	            expandedXDimNum != NUM_THREE, OP_LOGE(context_, "The dim number of expandedX should be %ld.", NUM_THREE),
590	            return ge::GRAPH_FAILED);
591	        OP_CHECK_IF(
592	            expandedXShape.GetDim(0) != expertNum_,
593	            OP_LOGE(context_, "The first dim of expandedX should be %ld.", expertNum_), return ge::GRAPH_FAILED);
594	        OP_CHECK_IF(
595	            expandedXShape.GetDim(1) != expertCapacity_,
596	            OP_LOGE(context_, "The second dim of expandedX should be %ld.", expertCapacity_), return ge::GRAPH_FAILED);
597	        OP_CHECK_IF(
598	            expandedXShape.GetDim(NUM_TWO) != cols_,
599	            OP_LOGE(context_, "The third dim of expandedX should be %ld.", cols_), return ge::GRAPH_FAILED);
600	    } else {
601	        OP_CHECK_IF(
602	            expandedXDimNum != DIM_TWO, OP_LOGE(context_, "The dim number of expandedX should be 2."),
603	            return ge::GRAPH_FAILED);
604	        int64_t firstDim = totalLength_;
605	        firstDim = activeNum_ == 0 ? firstDim : std::min(firstDim, activeNum_);
606	        OP_CHECK_IF(
607	            expandedXShape.GetDim(0) != firstDim,
608	            OP_LOGE(context_, "The first dim of expandedX should be %ld.", firstDim), return ge::GRAPH_FAILED);
609	        OP_CHECK_IF(
610	            expandedXShape.GetDim(1) != cols_, OP_LOGE(context_, "The second dim of expandedX should be %ld.", cols_),
611	            return ge::GRAPH_FAILED);
612	    }
613	
614	    OP_CHECK_IF(
615	        expandedRowIdxShape.GetDimNum() != DIM_ONE,
616	        OP_LOGE(context_, "The dim number of expanded_row_idx should be 1."), return ge::GRAPH_FAILED);
617	    OP_CHECK_IF(
618	        expandedRowIdxShape.GetDim(0) != totalLength_,
619	        OP_LOGE(context_, "The first dim of expanded_row_idx and expanded_expert_idx should be %ld.", totalLength_),
620	        return ge::GRAPH_FAILED);
621	
622	    if (expertTokensNumFlag_) {
623	        if (expertTokensNumType_ == KEY_VALUE) {
624	            OP_CHECK_IF(
625	                expertTokensCountOrCumsumShape.GetDimNum() != DIM_TWO,
626	                OP_LOGE(
627	                    context_, "The dim number of expert_tokens_count_or_cumsum should be 2 when in KEY_VALUE mode."),
628	                return ge::GRAPH_FAILED);
629	            OP_CHECK_IF(
630	                expertTokensCountOrCumsumShape.GetDim(0) != expertNum_,
631	                OP_LOGE(context_, "The first dim of expert_tokens_count_or_cumsum should be %ld.", expertNum_),
632	                return ge::GRAPH_FAILED);
633	            OP_CHECK_IF(
634	                expertTokensCountOrCumsumShape.GetDim(1) != KEY_VALUE_MODE_DIM0_NUM,
635	                OP_LOGE(
636	                    context_, "The second dim of expert_tokens_count_or_cumsum should be %ld.",
637	                    KEY_VALUE_MODE_DIM0_NUM),
638	                return ge::GRAPH_FAILED);
639	        } else {
640	            OP_CHECK_IF(
641	                expertTokensCountOrCumsumShape.GetDimNum() != DIM_ONE,
642	                OP_LOGE(
643	                    context_,
644	                    "The dim number of expert_tokens_count_or_cumsum should be 1 when not in KEY_VALUE mode."),
645	                return ge::GRAPH_FAILED);
646	            OP_CHECK_IF(
647	                expertTokensCountOrCumsumShape.GetDim(0) != (expertEnd_ - expertStart_),
648	                OP_LOGE(
649	                    context_, "The first dim of expert_tokens_count_or_cumsum should be %ld.",
650	                    (expertEnd_ - expertStart_)),
651	                return ge::GRAPH_FAILED);
652	        }
653	    }
654	
655	    if (quantMode_ != STATIC_QUANT && scaleShapePtr_ != nullptr) {
656	        OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputShape(NUM_THREE));
657	        const gert::Shape expandedScaleShape = context_->GetOutputShape(3)->GetStorageShape();
658	        OP_LOGI(context_, "expanded_scale shape: %s.", OpsBaseToString(expandedScaleShape).c_str());
659	        size_t expandedScaleDimNum = expandedScaleShape.GetDimNum();
660	        OP_CHECK_IF(
661	            expandedScaleDimNum != DIM_ONE, OP_LOGE(context_, "The dim number of expanded_scale should be 1."),
662	            return ge::GRAPH_FAILED);
663	        if (dropPadMode_ > 0) {
664	            OP_CHECK_IF(
665	                expandedScaleShape.GetDim(0) != expertNum_ * expertCapacity_,
666	                OP_LOGE(context_, "The first dim of expanded_scale should be %ld.", expertNum_ * expertCapacity_),
667	                return ge::GRAPH_FAILED);
668	        } else {
669	            int64_t firstDim = totalLength_;
670	            firstDim = activeNum_ == 0 ? firstDim : std::min(firstDim, activeNum_);
671	            OP_CHECK_IF(
672	                expandedScaleShape.GetDim(0) != firstDim,
673	                OP_LOGE(context_, "The first dim of expanded_scale should be %ld.", firstDim), return ge::GRAPH_FAILED);
674	        }
675	    }
676	
677	    return ge::GRAPH_SUCCESS;
678	}
