751	int64_t MoeInitRountingV3TilingBase::IsGatherFirstFullLoad()
752	{
753	    // 判断当前输入条件下，要不要先gather(剔除无效专家)再排序.
754	    if (ep_ == 0) {
755	        return 0;
756	    } else if (n_ >= gatherFirstN && (expertEnd_ - expertStart_) * gatherFirstScale <= expertNum_) {
757	        return 1;
758	    } else {
759	        return 0;
760	    }
