763	bool MoeInitRountingV3TilingBase::IsFullLoad()
764	{
765	    int64_t perCoreTokens = 1;
766	    if (expertStart_ == 0 && expertEnd_ == expertNum_) {
767	        ep_ = 0;
768	        if (quantMode_ != 1) {
769	            perCoreTokens = n_ / aivNum;
770	            int64_t remainder = n_ % aivNum;
771	            // NUM_TWO is Max xRows need add 2 becauseof the left and right row may be another row.
772	            perCoreTokens = remainder <= 1 ? perCoreTokens + 1 : perCoreTokens + NUM_TWO;
773	        }
774	    } else {
775	        ep_ = 1;
776	        perCoreTokens = 1;
777	    }
778	    moeInitRoutingV3TilingData.set_ep(ep_);
779	
780	    if (totalLength_ > sortLoopMaxElement || this->dropPadMode_ == 1) {
781	        return false;
782	    }
783	
784	    gatherFirstFullload_ = IsGatherFirstFullLoad();
785	    moeInitRoutingV3TilingData.set_gatherFirstFullload(gatherFirstFullload_);
786	    int64_t tileLength = Align(this->totalLength_, int64_t(sizeof(int32_t)));
787	    int64_t sortNum = OpsBaseCeilDiv(tileLength, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
788	
789	    int64_t sortSpace = sortNum * sizeof(int32_t) * ONE_CORE_SORT_BUFFER;
790	    int64_t rowIdxSpace = sortNum * sizeof(int32_t) * NUM_THREE;
791	    int64_t expertSpace =
792	        OpsBaseCeilDiv(this->expertNum_ * int64_t(sizeof(int64_t)), ONE_BLOCK_BYTE) * ONE_BLOCK_BYTE * NUM_TWO;
793	    int64_t gatherSpace = OpsBaseCeilDiv(cols_ * inuptXDtypeSize_, ONE_BLOCK_BYTE) * ONE_BLOCK_BYTE * perCoreTokens;
794	    int64_t remainUb = aicoreParams_.ubSize - sortSpace - rowIdxSpace - expertSpace - LENGTH_1024;
795	
796	    if (quantMode_ == -1) {
797	        remainUb -= (gatherSpace + ONE_BLOCK_BYTE);
798	    } else if (quantMode_ == 0) {
799	        int64_t quantSpace = 0;
800	        int64_t xAlignedCount = Align(this->cols_, int64_t(sizeof(int8_t)));
801	        quantSpace = xAlignedCount * STATIC_QUANT_FULLLOAD_COLS_BUFFER * perCoreTokens;
802	        remainUb -= (gatherSpace + quantSpace);
803	    } else {
804	        int64_t quantSpace =
805	            OpsBaseCeilDiv(cols_, ONE_BLOCK_BYTE) * ONE_BLOCK_BYTE * DYNAMIC_QUANT_FULLLOAD_COLS_BUFFER;
806	        int64_t scaleOutSpace = ONE_BLOCK_BYTE * NUM_TWO;
807	        remainUb -= (quantSpace + scaleOutSpace);
808	    }
809	    return remainUb > 0;
810	}
811	
812	void MoeInitRountingV3TilingBase::ComputeCountingSortTiling()
813	{
814	    int64_t actualExpertNum = expertEnd_ - expertStart_;
815	    if (n_ < COUNTING_SORT_MIN_N || n_ > COUNTING_SORT_MAX_N || ep_ != 1 || quantMode_ != UN_QUANT ||
816	        dropPadMode_ != DROP_LESS || expertTokensNumType_ != COUNT ||
817	        actualExpertNum > COUNTING_SORT_MAX_ACTUAL_EXPERT_NUM || actualExpertNum <= 0 || k_ != PERFORMANCE_MODE_TOP_K) {
818	        return;
819	    }
820	    if (n_ <= COUNTING_SORT_THRESHOLD && rowIdxTytpe_ == SCATTER &&
821	        (expertEnd_ - expertStart_) <= PERFORMANCE_MODE_RANGE_MAX) {
822	        return;
823	    }
824	
825	    int64_t ubSize = static_cast<int64_t>(aicoreParams_.ubSize);
826	    int64_t filterPerCoreTokens = OpsBaseCeilDiv(n_, aivNum);
827	    int64_t filterNeedCoreNum = OpsBaseCeilDiv(n_, filterPerCoreTokens);
828	    int64_t expertCountStride = OpsBaseCeilAlign(actualExpertNum, ONE_BLOCK_ELEMENT);
829	    int64_t coreEntries = filterPerCoreTokens * k_;
830	    int64_t fullLoadUB = EstimateCountingSortFullLoadUB(
831	        filterPerCoreTokens, coreEntries, expertCountStride, filterNeedCoreNum, actualExpertNum);
832	
833	    countingSortFullLoad_ = (fullLoadUB <= ubSize - LENGTH_1024) ? 1 : 0;
834	    int64_t filterChunkSize = (countingSortFullLoad_ == 1) ? 0 : COUNTING_SORT_FILTER_CHUNK_SIZE;
835	
836	    if (countingSortFullLoad_ == 1) {
837	        countingSortWorkspaceSize_ =
838	            static_cast<size_t>(filterNeedCoreNum) * static_cast<size_t>(expertCountStride) * sizeof(int32_t);
839	        moeInitRoutingV3TilingData.gatherOutComputeParamsOp.set_needCoreNum(filterNeedCoreNum);
840	        moeInitRoutingV3TilingData.gatherOutComputeParamsOp.set_perCoreIndicesElements(filterPerCoreTokens);
841	    } else {
842	        ComputeCountingSortCutOriginTiling(filterNeedCoreNum, filterPerCoreTokens, expertCountStride, actualExpertNum);
843	    }
844	
845	    OP_LOGI(
846	        context_,
847	        "CountingSort tiling: countingSortFullLoad=%ld, filterNeedCoreNum=%ld, "
848	        "filterPerCoreTokens=%ld, filterChunkSize=%ld, fullLoadUB=%ld, ubSize=%ld, "
849	        "countingSortWorkspaceSize=%zu",
850	        countingSortFullLoad_, filterNeedCoreNum, filterPerCoreTokens, filterChunkSize, fullLoadUB, ubSize,
851	        countingSortWorkspaceSize_);
852	}
853	
854	int64_t MoeInitRountingV3TilingBase::EstimateCountingSortFullLoadUB(
855	    int64_t coreTokenNum, int64_t coreEntries, int64_t expertCountStride, int64_t filterNeedCoreNum,
856	    int64_t actualExpertNum)
857	{
858	    int64_t colsAligned = OpsBaseCeilDiv(cols_ * inuptXDtypeSize_, ONE_BLOCK_BYTE) * ONE_BLOCK_BYTE / inuptXDtypeSize_;
859	    int64_t scaleSlotSize = ONE_BLOCK_BYTE / SIZE_FP32;
860	    int64_t ub = 0;
861	
862	    ub += OpsBaseCeilAlign(coreTokenNum * colsAligned * inuptXDtypeSize_, ONE_BLOCK_BYTE);
863	    ub += OpsBaseCeilAlign(coreEntries * SIZE_INT32, ONE_BLOCK_BYTE);
864	    if (isInputScale_) {
865	        ub += OpsBaseCeilAlign(coreTokenNum * scaleSlotSize * SIZE_FP32, ONE_BLOCK_BYTE);
866	    }
867	    ub += OpsBaseCeilAlign(expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
868	    ub += OpsBaseCeilAlign(filterNeedCoreNum * expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
869	    ub += OpsBaseCeilAlign(actualExpertNum * static_cast<int64_t>(sizeof(int64_t)), ONE_BLOCK_BYTE);
870	    ub += OpsBaseCeilAlign(expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
871	    ub += OpsBaseCeilAlign(coreEntries * NUM_TWO * SIZE_INT32, ONE_BLOCK_BYTE);
872	
873	    int64_t entriesAligned =
874	        OpsBaseCeilDiv(coreEntries, COUNTING_SORT_ONE_REPEAT_COMPARE_NUM) * COUNTING_SORT_ONE_REPEAT_COMPARE_NUM;
875	    int64_t maskBytes = OpsBaseCeilAlign(OpsBaseCeilDiv(entriesAligned, ONE_BLOCK_ELEMENT), ONE_BLOCK_BYTE);
876	    ub += OpsBaseCeilAlign(entriesAligned * SIZE_FP32, ONE_BLOCK_BYTE);
877	    ub += maskBytes * NUM_THREE;
878	    ub += OpsBaseCeilAlign(entriesAligned * SIZE_INT32, ONE_BLOCK_BYTE) * NUM_THREE;
879	
880	    return ub;
881	}
882	
883	void MoeInitRountingV3TilingBase::ComputeCountingSortCutOriginTiling(
884	    int64_t filterNeedCoreNum, int64_t filterPerCoreTokens, int64_t expertCountStride, int64_t actualExpertNum)
885	{
886	    int64_t chunkAligned = OpsBaseCeilAlign(COUNTING_SORT_FILTER_CHUNK_SIZE, ONE_BLOCK_ELEMENT);
887	    int64_t persistentSize = OpsBaseCeilAlign(expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
888	    // Phase A: chunked filtering
889	    int64_t phaseASize = OpsBaseCeilAlign(chunkAligned * SIZE_INT32, ONE_BLOCK_BYTE);
890	    phaseASize += OpsBaseCeilAlign(chunkAligned * SIZE_FP32, ONE_BLOCK_BYTE);
891	    int64_t maskBytesA =
892	        OpsBaseCeilAlign(OpsBaseCeilDiv(chunkAligned, ONE_BLOCK_ELEMENT), static_cast<int64_t>(sizeof(int8_t)));
893	    phaseASize += maskBytesA * NUM_THREE + OpsBaseCeilAlign(chunkAligned * SIZE_INT32, ONE_BLOCK_BYTE) * NUM_THREE;
894	    phaseASize += OpsBaseCeilAlign(chunkAligned * NUM_TWO * SIZE_INT32, ONE_BLOCK_BYTE);
895	
896	    // Phase B
897	    int64_t phaseBSize = OpsBaseCeilAlign(filterNeedCoreNum * expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
898	    phaseBSize += OpsBaseCeilAlign(expertCountStride * SIZE_INT32, ONE_BLOCK_BYTE);
899	    phaseBSize += OpsBaseCeilAlign(actualExpertNum * static_cast<int64_t>(sizeof(int64_t)), ONE_BLOCK_BYTE);
900	
901	    // Phase C: compute colsLoops/perLoopCols
902	    int64_t maxPerLoopColsBytes = COUNTING_SORT_MAX_PER_LOOP_COLS_BYTES;
903	    int64_t csPerLoopCols =
904	        (cols_ * inuptXDtypeSize_ > maxPerLoopColsBytes) ? (maxPerLoopColsBytes / inuptXDtypeSize_) : cols_;
905	    int64_t csColsLoops = OpsBaseCeilDiv(cols_, csPerLoopCols);
906	    int64_t csLastLoopCols = cols_ - (csColsLoops - 1) * csPerLoopCols;
907	    int64_t csPerLoopColsAligned =
908	        OpsBaseCeilDiv(csPerLoopCols * inuptXDtypeSize_, ONE_BLOCK_BYTE) * ONE_BLOCK_BYTE / inuptXDtypeSize_;
909	
910	    int64_t phaseCSize = OpsBaseCeilAlign(chunkAligned * NUM_TWO * SIZE_INT32, ONE_BLOCK_BYTE);
911	    phaseCSize += ONE_BLOCK_BYTE + OpsBaseCeilAlign(csPerLoopColsAligned * inuptXDtypeSize_, ONE_BLOCK_BYTE);
912	    if (isInputScale_) {
913	        phaseCSize += OpsBaseCeilAlign(ONE_BLOCK_ELEMENT * SIZE_FP32, ONE_BLOCK_BYTE);
914	    }
915	
916	    int64_t totalUB = persistentSize + std::max({phaseASize, phaseBSize, phaseCSize});
917	
918	    // Set tiling params
919	    auto gatherOp = &moeInitRoutingV3TilingData.gatherOutComputeParamsOp;
920	    gatherOp->set_needCoreNum(filterNeedCoreNum);
921	    gatherOp->set_perCoreIndicesElements(filterPerCoreTokens);
922	    gatherOp->set_colsLoops(csColsLoops);
923	    gatherOp->set_perLoopCols(csPerLoopCols);
924	    gatherOp->set_lastLoopCols(csLastLoopCols);
925	
926	    // Workspace: pairs + expertCount
927	    int64_t lastCoreTokens = n_ - (filterNeedCoreNum - 1) * filterPerCoreTokens;
928	    int64_t maxCoreEntries = std::max(filterPerCoreTokens, lastCoreTokens) * k_;
929	    int64_t pairsPerCore = OpsBaseCeilAlign(maxCoreEntries, ONE_BLOCK_ELEMENT) * NUM_TWO;
930	    size_t pairsWorkspaceSize =
931	        static_cast<size_t>(filterNeedCoreNum) * static_cast<size_t>(pairsPerCore) * sizeof(int32_t);
932	    size_t expertCountWorkspaceSize =
933	        static_cast<size_t>(filterNeedCoreNum) * static_cast<size_t>(expertCountStride) * sizeof(int32_t);
934	    countingSortWorkspaceSize_ = pairsWorkspaceSize + expertCountWorkspaceSize;
935	}
