937	bool MoeInitRountingV3TilingBase::IsPerformanceMode() const
938	{
939	    OP_LOGI(context_, "Begin IsPerformanceMode() ...");
940	    bool result = false;
941	
942	    // 性能模板： 当前支持 ((1, 7168), (1, 8),(256, 7168),None) ('bfloat16', 'int32','float32','float32')
943	    // expert_range [0,256), quant_mode=DYNAMIC_QUANT
944	    const gert::Shape performXShape_X_1_7168 = gert::Shape({1, 7168});
945	    const gert::Shape performExpertIdxShape_X_1_7168 = gert::Shape({1, 8});
946	    const gert::Shape performScaleShape_X_1_7168 = gert::Shape({256, 7168});
947	
948	    OP_CHECK_NULL_WITH_CONTEXT(context_, xShapePtr_);
949	    OP_CHECK_NULL_WITH_CONTEXT(context_, expertIdxShapePtr_);
950	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputDesc(INPUT_X_INDEX));
951	    if (nullptr == scaleShapePtr_) {
952	        result = false;
953	    } else if (
954	        xShapePtr_->GetStorageShape() == performXShape_X_1_7168 &&
955	        expertIdxShapePtr_->GetStorageShape() == performExpertIdxShape_X_1_7168 &&
956	        scaleShapePtr_->GetStorageShape() == performScaleShape_X_1_7168 && offsetShapePtr_ == nullptr &&
957	        context_->GetInputDesc(INPUT_X_INDEX)->GetDataType() == ge::DT_BF16 && expertStart_ == 0 &&
958	        expertEnd_ == ASSIST_NUM && quantMode_ == DYNAMIC_QUANT && expertTokensNumType_ == KEY_VALUE) {
959	        result = true;
960	    } else {
961	        OP_LOGI(context_, "Not IsPerformanceMode() ...");
962	    }
963	    OP_LOGI(context_, "End IsPerformanceMode() ...");
964	    return result;
965	}
