967	PerformanceMode MoeInitRountingV3TilingBase::GetPerformanceMode() const
968	{
969	    PerformanceMode result = PerformanceMode::COMMON;
970	    if (expertNum_ != ASSIST_NUM || (expertEnd_ - expertStart_) > PERFORMANCE_MODE_RANGE_MAX ||
971	        n_ < PERFORMANCE_MODE_BS_MIN || n_ > PERFORMANCE_MODE_BS_MAX || k_ != PERFORMANCE_MODE_TOP_K) {
972	        return result;
973	    }
974	
975	    // Judge performance mode according to totalLength_
976	    if (totalLength_ < PERFORMANCE_MODE_MAX_ONE_CORE_GATHER) {
977	        OP_LOGI(context_, "totalLength_: %ld, PerformanceMode::ONE_CORE_GATHER_SORT", totalLength_);
978	        result = PerformanceMode::ONE_CORE_GATHER_SORT;
979	    } else if (totalLength_ <= PERFORMANCE_MODE_MAX_BATCH_SIZE_TOP_K) {
980	        OP_LOGI(context_, "totalLength_: %ld, PerformanceMode::MULTI_CORE_GATHER_SORT", totalLength_);
981	        result = PerformanceMode::MULTI_CORE_GATHER_SORT;
