1009	        OP_CHECK_IF(
1010	            scaleDtype_ != ge::DT_FLOAT, OP_LOGE(context_, "The data type of input_scale should be FLOAT."),
1011	            return ge::GRAPH_FAILED);
1012	
1013	        OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOptionalInputDesc(INPUT_OFFSET_INDEX));
1014	        auto offsetDtype_ = context_->GetOptionalInputDesc(INPUT_OFFSET_INDEX)->GetDataType();
1015	        OP_CHECK_IF(
1016	            offsetDtype_ != ge::DT_FLOAT, OP_LOGE(context_, "The data type of input_offset should be FLOAT."),
1017	            return ge::GRAPH_FAILED);
1018	    } else {
1019	        if (scaleShapePtr_ != nullptr) {
1020	            OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOptionalInputDesc(INPUT_SCALE_INDEX));
1021	            auto scaleDtype_ = context_->GetOptionalInputDesc(INPUT_SCALE_INDEX)->GetDataType();
1022	            OP_CHECK_IF(
1023	                scaleDtype_ != ge::DT_FLOAT, OP_LOGE(context_, "The data type of input_scale should be FLOAT."),
