1025	        }
1026	    }
1027	
1028	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputDesc(OUTPUT_EXPANDED_X_INDEX));
1029	    auto expandedXDtype_ = context_->GetOutputDesc(OUTPUT_EXPANDED_X_INDEX)->GetDataType();
1030	    OP_CHECK_IF(
1031	        expandedXDtype_ != ge::DT_INT8 && expandedXDtype_ != ge::DT_FLOAT16 && expandedXDtype_ != ge::DT_BF16 &&
1032	            expandedXDtype_ != ge::DT_FLOAT,
1033	        OP_LOGE(context_, "The data type of output_expanded_X should be INT8, FLOAT16, BF16, FLOAT."),
1034	        return ge::GRAPH_FAILED);
1035	
1036	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputDesc(OUTPUT_EXPANDED_ROW_IDX_INDEX));
1037	    auto expandedRowIdxDtype_ = context_->GetOutputDesc(OUTPUT_EXPANDED_ROW_IDX_INDEX)->GetDataType();
1038	    OP_CHECK_IF(
1039	        expandedRowIdxDtype_ != ge::DT_INT32,
1040	        OP_LOGE(context_, "The data type of output_expanded_row_idx should be INT32."), return ge::GRAPH_FAILED);
1041	
1042	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputDesc(OUTPUT_EXPERT_TOKENS_COUNT_INDEX));
1043	    auto expertTokensCountOrCusumDtype_ = context_->GetOutputDesc(OUTPUT_EXPERT_TOKENS_COUNT_INDEX)->GetDataType();
1044	    OP_CHECK_IF(
1045	        expertTokensCountOrCusumDtype_ != ge::DT_INT64,
1046	        OP_LOGE(context_, "The data type of output_expert_tokens_count_or_cumsum should be INT64."),
1047	        return ge::GRAPH_FAILED);
1048	
1049	    if (quantMode_ == DYNAMIC_QUANT || (quantMode_ == UN_QUANT && scaleShapePtr_ != nullptr)) {
1050	        OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetOutputDesc(OUTPUT_EXPANDED_SCALE_INDEX));
1051	        auto expandedScaleDtype_ = context_->GetOutputDesc(OUTPUT_EXPANDED_SCALE_INDEX)->GetDataType();
1052	        OP_CHECK_IF(
1053	            expandedScaleDtype_ != ge::DT_FLOAT,
1054	            OP_LOGE(context_, "The data type of input_expanded_scale should be FLOAT."), return ge::GRAPH_FAILED);
