1060	ge::graphStatus MoeInitRountingV3TilingBase::DoOpTiling()
1061	{
1062	    auto ret = CheckAttr();
1063	    if (ret != ge::GRAPH_SUCCESS) {
1064	        return ret;
1065	    }
1066	
1067	    ret = CheckInputShape();
1068	    if (ret != ge::GRAPH_SUCCESS) {
1069	        return ret;
1070	    }
1071	
1072	    ret = CheckOutShape();
1073	    if (ret != ge::GRAPH_SUCCESS) {
1074	        return ret;
1075	    }
1076	
1077	    ret = CheckDtype();
1078	    if (ret != ge::GRAPH_SUCCESS) {
1079	        return ret;
1080	    }
1081	
1082	    // 空tensor快速返回，跳过后续tiling计算
1083	    if (isEmptyTensor_) {
1084	        return ge::GRAPH_SUCCESS;
1085	    }
1086	
1087	    if (IsPerformanceMode()) {
1088	        aivNum = totalLength_;
1089	    }
1090	
1091	    sortLoopMaxElement = (aicoreParams_.ubSize - aivNum * ONE_BLOCK_BYTE) / (NUM_FOUR * NUM_TWO * NUM_FOUR) /
1092	                         SORT32_ALIGN_ELEMENT * SORT32_ALIGN_ELEMENT;
1093	
1094	    Tiling4VBSCompute();
1095	    Tiling4VMSMiddleCompute();
1096	    Tiling4SortOutCompute();
1097	    Tiling4ExpertTokensCountCompute();
1098	    Tiling4SrcToDstCompute();
1099	    Tiling4SrcToDstDropPadCompute();
1100	    Tiling4GatherOutCompute();
1101	    isFullload_ = IsFullLoad();
1102	    if (!isFullload_ && !IsPerformanceMode()) {
1103	        ComputeCountingSortTiling();
1104	    }
1105	    ShowTilingData();
1106	    return ge::GRAPH_SUCCESS;
1107	}
