1114	uint64_t MoeInitRountingV3TilingBase::GetTilingKey() const
1115	{
1116	    if (isEmptyTensor_) {
1117	        return EMPTY_TENSOR_TILINGKEY;
1118	    }
1119	
1120	    if (isFullload_) {
1121	        if (quantMode_ == UN_QUANT) {
1122	            return UNQUANTIZED_FULLLOAD_TILINGKEY;
1123	        } else if (quantMode_ == STATIC_QUANT) {
1124	            return STATIC_QUANT_FULLLOAD_TILINGKEY;
1125	        } else {
1126	            return (
1127	                DYNAMIC_QUANT_FULLLOAD_TILINGKEY + ep_ * DYNAMIC_QUANT_EPFULLLOAD_TILINGKEY +
1128	                smoothType_ * DYNAMIC_QUANT_SMOOTHTYPE_FULLLOAD_TILINGKEY);
1129	        }
1130	    } else if (IsPerformanceMode()) {
1131	        return PERFORMANCE_TILINGKEY_X_1_7168_EXPERT_IDX_1_8_SCALE_256_7168;
1132	    } else if (
1133	        countingSortFullLoad_ == 1 ||
1134	        (PerformanceMode::ONE_CORE_GATHER_SORT == GetPerformanceMode() && quantMode_ == UN_QUANT &&
1135	         rowIdxTytpe_ == SCATTER && expertTokensNumType_ == COUNT && countingSortFullLoad_ == -1)) {
1136	        uint64_t sortMode = NUM_TWO;
1137	        return static_cast<uint64_t>(
1138	            TILINGKEY_BASE + sortMode * SORT_CORE_TILINGKEY_BASE +
1139	            static_cast<uint64_t>(quantMode_ + 1) * QUANT_MODE_TILINGKEY_BASE +
1140	            static_cast<uint64_t>(rowIdxTytpe_) * ROWIDX_TYPE_TILINGKEY_BASE +
1141	            static_cast<uint64_t>(dropPadMode_) * DROP_MODE_TILINGKEY_BASE);
1142	    } else if (
1143	        countingSortFullLoad_ == 0 ||
1144	        (PerformanceMode::MULTI_CORE_GATHER_SORT == GetPerformanceMode() && quantMode_ == UN_QUANT &&
1145	         rowIdxTytpe_ == SCATTER && expertTokensNumType_ == COUNT && countingSortFullLoad_ == -1)) {
1146	        uint64_t sortMode = 3;
1147	        return static_cast<uint64_t>(
1148	            TILINGKEY_BASE + sortMode * SORT_CORE_TILINGKEY_BASE +
1149	            static_cast<uint64_t>(quantMode_ + 1) * QUANT_MODE_TILINGKEY_BASE +
1150	            static_cast<uint64_t>(rowIdxTytpe_) * ROWIDX_TYPE_TILINGKEY_BASE +
1151	            static_cast<uint64_t>(dropPadMode_) * DROP_MODE_TILINGKEY_BASE);
1152	    } else {
1153	        return static_cast<uint64_t>(
1154	            TILINGKEY_BASE + static_cast<uint64_t>(sortMode_) * SORT_CORE_TILINGKEY_BASE +
1155	            static_cast<uint64_t>(quantMode_ + 1) * QUANT_MODE_TILINGKEY_BASE +
1156	            static_cast<uint64_t>(rowIdxTytpe_) * ROWIDX_TYPE_TILINGKEY_BASE +
1157	            static_cast<uint64_t>(dropPadMode_) * DROP_MODE_TILINGKEY_BASE);
1158	    }
1159	}
