1161	ge::graphStatus MoeInitRountingV3TilingBase::GetWorkspaceSize()
1162	{
1163	    // 计算workspace大小
1164	    if (isEmptyTensor_) {
1165	        workspaceSize_ = SIZE_16 * LENGTH_1024 * LENGTH_1024;
1166	        return ge::GRAPH_SUCCESS;
1167	    }
1168	    size_t sortWorkspaceSize =
1169	        sizeof(float) * static_cast<size_t>(totalLength_ * NUM_TWO * NUM_THREE); // 排序需要的空间
1170	    size_t coreSyncWorkspaceSize =
1171	        moeInitRoutingV3TilingData.get_coreNum() * SORT32_ALIGN_ELEMENT * NUM_TWO; // 多核同步需要的空间
1172	    size_t scatterWorkspaceSize = sizeof(int32_t) * static_cast<size_t>(totalLength_);
1173	    size_t expertIdxValueWorkspaceSize = sizeof(int32_t) * static_cast<size_t>(aivNum) * 2U;
1174	    size_t expertTokensCountWorkspaceSize = sizeof(int32_t) * static_cast<size_t>((expertEnd_ - expertStart_));
1175	    int64_t expertTokenTotalCountWorkspace = AlignBytes(1, static_cast<int64_t>(sizeof(int32_t)));
1176	    int64_t quantTempWorkspaceSize = aivNum * cols_ * static_cast<int64_t>(sizeof(float));
1177	    workspaceSize_ = sortWorkspaceSize + coreSyncWorkspaceSize + scatterWorkspaceSize + expertTokensCountWorkspaceSize +
1178	                     expertTokenTotalCountWorkspace + SIZE_16 * LENGTH_1024 * LENGTH_1024;
1179	    if (quantMode_ == DYNAMIC_QUANT) {
1180	        workspaceSize_ += quantTempWorkspaceSize;
1181	    }
1182	    if (dropPadMode_ == DROP_PAD) {
1183	        workspaceSize_ += expertIdxValueWorkspaceSize;
1184	    }
1185	    // Counting sort may need additional workspace
1186	    if (countingSortWorkspaceSize_ > workspaceSize_) {
1187	        workspaceSize_ = countingSortWorkspaceSize_;
1188	    }
1189	    OP_LOGI(context_, "Allocate workspaceSize is: %ld.", workspaceSize_);
1190	    return ge::GRAPH_SUCCESS;
1191	}
