1207	void MoeInitRountingV3TilingBase::Tinlig4VBSOneCoreCompute(MoeV3VBSComputeTilingData* tilingData)
1208	{
1209	    tilingData->set_needCoreNum(1);
1210	    tilingData->set_perCoreElements(totalLength_);
1211	    tilingData->set_perCoreLoops(1);
1212	    tilingData->set_perCorePerLoopElements(tilingData->get_perCoreElements());
1213	    tilingData->set_perCoreLastLoopElements(tilingData->get_perCoreElements());
1214	    tilingData->set_lastCoreElements(tilingData->get_perCoreElements());
1215	    tilingData->set_lastCoreLoops(1);
1216	    tilingData->set_lastCorePerLoopElements(tilingData->get_perCoreElements());
1217	    tilingData->set_lastCoreLastLoopElements(tilingData->get_perCoreElements());
1218	}
