1220	void MoeInitRountingV3TilingBase::Tinlig4VBSMultiCoreCompute(MoeV3VBSComputeTilingData* tilingData)
1221	{
1222	    int64_t needCoreNum = OpsBaseCeilDiv(totalLength_, sortLoopMaxElement);        // 向上取整
1223	    needCoreNum = static_cast<int64_t>(std::pow(NUM_FOUR, CeilLog4(needCoreNum))); // 用到多核时，核数最多是4^x
1224	    needCoreNum = std::min(needCoreNum, aivNum);                                   // 不能超过物理核数
1225	
1226	    OP_CHECK_IF(needCoreNum == 0, OP_LOGE(context_, "Variale needCoreNum cannot be 0."), return;);
1227	    int64_t perCoreElements = (needCoreNum == 0) ? 0 : (totalLength_ / needCoreNum);
1228	    int64_t alineFloorPerCoreElements = perCoreElements - perCoreElements % SORT32_ALIGN_ELEMENT;
1229	    int64_t lastCoreElement = totalLength_ - (needCoreNum - 1) * alineFloorPerCoreElements;
1230	    int64_t alineCeilPerCoreElements = perCoreElements + SORT32_ALIGN_ELEMENT - perCoreElements % SORT32_ALIGN_ELEMENT;
1231	    if (lastCoreElement > alineCeilPerCoreElements) {
1232	        perCoreElements = alineCeilPerCoreElements;
1233	        needCoreNum = OpsBaseCeilDiv(totalLength_, perCoreElements);
1234	    } else {
1235	        perCoreElements = alineFloorPerCoreElements;
1236	    }
1237	
1238	    tilingData->set_needCoreNum(needCoreNum);
1239	    do {
1240	        tilingData->set_perCoreElements(perCoreElements);
1241	        tilingData->set_perCoreLoops(
1242	            OpsBaseCeilDiv(tilingData->get_perCoreElements(), sortLoopMaxElement)); // 每个核处理的loop数
1243	        tilingData->set_perCorePerLoopElements(std::min(tilingData->get_perCoreElements(), sortLoopMaxElement));
1244	
1245	        tilingData->set_perCoreLastLoopElements(
1246	            tilingData->get_perCoreElements() -
1247	            (tilingData->get_perCoreLoops() - 1) * tilingData->get_perCorePerLoopElements());
1248	
1249	        tilingData->set_lastCoreElements(
1250	            totalLength_ - (tilingData->get_needCoreNum() - 1) * tilingData->get_perCoreElements());
1251	        tilingData->set_lastCoreLoops(tilingData->get_perCoreLoops());
1252	        int64_t lastCorePerLoopElements =
1253	            OpsBaseCeilDiv(
1254	                OpsBaseCeilDiv(tilingData->get_lastCoreElements(), tilingData->get_lastCoreLoops()),
1255	                SORT32_ALIGN_ELEMENT) *
1256	            SORT32_ALIGN_ELEMENT;
1257	        tilingData->set_lastCorePerLoopElements(lastCorePerLoopElements);
1258	        tilingData->set_lastCoreLastLoopElements(
1259	            tilingData->get_lastCoreElements() -
1260	            (tilingData->get_lastCoreLoops() - 1) * tilingData->get_lastCorePerLoopElements());
1261	        perCoreElements -= SORT32_ALIGN_ELEMENT;
1262	    } while (tilingData->get_lastCoreLastLoopElements() <= 0 && perCoreElements > 0);
1263	    OP_CHECK_IF(tilingData->get_lastCoreLastLoopElements() <= 0, OP_LOGE(context_, "vbs tiling failed"), ;);
1264	}
1265	
1266	void MoeInitRountingV3TilingBase::Tiling4VBSCompute()
1267	{
1268	    if (totalLength_ <= sortLoopMaxElement) { // 排序只用到一个核排序
1269	        sortMode_ = 0;
1270	    } else {
1271	        sortMode_ = 1;
1272	    }
1273	
1274	    auto tilingData = &moeInitRoutingV3TilingData.vbsComputeParamsOp;
1275	    tilingData->set_oneLoopMaxElements(sortLoopMaxElement);
1276	    if (sortMode_ == 0UL) { // 只用到一个核
1277	        Tinlig4VBSOneCoreCompute(tilingData);
1278	        return;
1279	    }
1280	    Tinlig4VBSMultiCoreCompute(tilingData);
1281	}
