1283	void MoeInitRountingV3TilingBase::Tiling4VMSMiddleCompute()
1284	{
1285	    auto vbsComputeTilingData = &moeInitRoutingV3TilingData.vbsComputeParamsOp;
1286	    auto tilingData = &moeInitRoutingV3TilingData.vmsMiddleComputeParamsOp;
1287	    if (vbsComputeTilingData->get_needCoreNum() <= MRG_LIST_NUM) { // 队列数小于一次vms则没有中间归并
1288	        tilingData->set_needCoreNum(0);                            // 需要的核数
1289	        return;
1290	    }
1291	    int64_t needCoreNum = OpsBaseCeilDiv(vbsComputeTilingData->get_needCoreNum(), MRG_LIST_NUM);
1292	    tilingData->set_needCoreNum(needCoreNum); // 需要的核数
1293	}
