1300	
1301	void MoeInitRountingV3TilingBase::Tiling4ExpertTokensCountCompute()
1302	{
1303	    auto tilingData = &moeInitRoutingV3TilingData.expertTokensCountTilingDataOp;
1304	    int64_t totalElements = moeInitRoutingV3TilingData.get_n() * moeInitRoutingV3TilingData.get_k();
1305	    int64_t perCoreElements = OpsBaseCeilDiv(totalElements, aivNum);
1306	    int64_t needCoreNum = OpsBaseCeilDiv(totalElements, perCoreElements);
1307	    int64_t lastCoreElements = totalElements - (needCoreNum - 1) * perCoreElements;
1308	    tilingData->set_needCoreNum(needCoreNum);
1309	    tilingData->set_perCoreElements(perCoreElements);
1310	    tilingData->set_lastCoreElements(lastCoreElements);
1311	
1312	    int64_t expertNumElement = (moeInitRoutingV3TilingData.get_expertTokensNumType() != KEY_VALUE) ?
1313	                                   moeInitRoutingV3TilingData.get_actualExpertNum() :
1314	                                   (moeInitRoutingV3TilingData.get_actualExpertNum() + 1) * DIM_TWO;
1315	
1316	    int64_t maxElementsPerLoop =
1317	        (static_cast<int64_t>(aicoreParams_.ubSize) -
1318	         OpsBaseCeilAlign(expertNumElement, ONE_BLOCK_BYTE) *
1319	             (static_cast<int64_t>(sizeof(int32_t)) * NUM_TWO + static_cast<int64_t>(sizeof(int64_t))) -
1320	         ONE_BLOCK_BYTE) /
1321	        static_cast<int64_t>(sizeof(int32_t));
1322	    int64_t perCoreLoops = OpsBaseCeilDiv(perCoreElements, maxElementsPerLoop);
1323	    int64_t perCorePerLoopElements = OpsBaseCeilDiv(perCoreElements, perCoreLoops);
1324	    int64_t perCoreLastLoopElements = perCoreElements - (perCoreLoops - 1) * perCorePerLoopElements;
1325	
1326	    tilingData->set_perCoreLoops(perCoreLoops);
1327	    tilingData->set_perCorePerLoopElements(perCorePerLoopElements);
1328	    tilingData->set_perCoreLastLoopElements(perCoreLastLoopElements);
1329	
1330	    int64_t lastCoreLoops = OpsBaseCeilDiv(lastCoreElements, maxElementsPerLoop);
1331	    int64_t lastCorePerLoopElements = OpsBaseCeilDiv(lastCoreElements, lastCoreLoops);
1332	    int64_t lastCoreLastLoopElements = lastCoreElements - (lastCoreLoops - 1) * lastCorePerLoopElements;
1333	
1334	    tilingData->set_lastCoreLoops(lastCoreLoops);
1335	    tilingData->set_lastCorePerLoopElements(lastCorePerLoopElements);
1336	    tilingData->set_lastCoreLastLoopElements(lastCoreLastLoopElements);
1337	
1338	    OP_LOGI(
1339	        context_,
1340	        "ExpertTokensCountCompute Tilingdata, needCoreNum is: %ld, perCoreElements is: %ld, lastCoreElements is: "
1341	        "%ld, maxElementsPerLoop is: %ld, perCoreLoops is: %ld, perCorePerLoopElements is: %ld, "
1342	        "perCoreLastLoopElements "
1343	        "is: %ld, lastCoreLoops is: %ld, lastCorePerLoopElements is: %ld, lastCoreLastLoopElements is: %ld.",
1344	        needCoreNum, perCoreElements, lastCoreElements, maxElementsPerLoop, perCoreLoops, perCorePerLoopElements,
1345	        perCoreLastLoopElements, lastCoreLoops, lastCorePerLoopElements, lastCoreLastLoopElements);
1346	}
1347	
1348	// 增加SrcToDstCapacity切分
1349	void MoeInitRountingV3TilingBase::Tiling4SrcToDstDropPadCompute()
1350	{
1351	    if (quantMode_ == DYNAMIC_QUANT && dropPadMode_ == DROP_PAD) {
1352	        MoeInitRountingV3TilingBase::Tiling4SrcToDstDropPadDynamicCompute();
1353	        return;
1354	    }
1355	
1356	    auto tilingData = &moeInitRoutingV3TilingData.srcToDstDropPadParamsOp;
1357	
1358	    int64_t perCoreRows = OpsBaseCeilDiv(totalLength_, aivNum);
1359	    if (perCoreRows <= 0) {
1360	        tilingData->set_needCoreNum(0);
1361	        return;
1362	    }
1363	    int64_t needCoreNum = OpsBaseCeilDiv(totalLength_, perCoreRows);
1364	    tilingData->set_needCoreNum(needCoreNum);
1365	    int64_t cols = moeInitRoutingV3TilingData.get_cols();
1366	    tilingData->set_perCoreRows(perCoreRows);
1367	    int64_t lastCoreRows = totalLength_ - perCoreRows * (needCoreNum - 1);
1368	    tilingData->set_lastCoreRows(lastCoreRows);
1369	    int64_t inuptXDtypeSize = inuptXDtypeSize_ == SIZE_INT8 ? SIZE_INT16 : inuptXDtypeSize_;
1370	
1371	    int64_t rowSize = (perCoreRows * sizeof(int32_t) * NUM_TWO + ONE_BLOCK_BYTE + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE *
1372	                      ONE_BLOCK_BYTE;
1373	    int64_t colSize = (cols * inuptXDtypeSize + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
1374	
1375	    if (rowSize + colSize < static_cast<int64_t>(aicoreParams_.ubSize)) { // 一行能够全载
1376	        SetGatherTilingData(tilingData, perCoreRows, lastCoreRows, cols);
1377	    } else {
1378	        int64_t baseMaxCols = MAX_COLS_ONE_LOOP;
1379	        int64_t baseMaxColsSize =
1380	            (baseMaxCols * inuptXDtypeSize + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
1381	        int64_t basePerLoopMaxRows = (static_cast<int64_t>(aicoreParams_.ubSize) - baseMaxColsSize - ONE_BLOCK_BYTE) /
1382	                                     static_cast<int64_t>(sizeof(int32_t)) / NUM_TWO / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
1383	        if (cols < MAX_COLS_ONE_LOOP) {
1384	            basePerLoopMaxRows = (static_cast<int64_t>(aicoreParams_.ubSize) - colSize - ONE_BLOCK_BYTE) /
1385	                                 static_cast<int64_t>(sizeof(int32_t)) / NUM_TWO / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
1386	        } else if (perCoreRows < basePerLoopMaxRows) {
1387	            baseMaxCols = (static_cast<int64_t>(aicoreParams_.ubSize) - rowSize) / inuptXDtypeSize / ONE_BLOCK_BYTE *
1388	                          ONE_BLOCK_BYTE;
1389	        }
1390	        tilingData->set_perLoopCols(std::min(baseMaxCols, cols));
1391	        tilingData->set_lastLoopCols(GetPerOrLastValue(cols, baseMaxCols));
1392	        tilingData->set_colLoops((cols + baseMaxCols - 1) / baseMaxCols);
1393	
1394	        tilingData->set_perCorePerLoopRows(std::min(perCoreRows, basePerLoopMaxRows));
1395	        tilingData->set_perCoreLastLoopRows(GetPerOrLastValue(perCoreRows, basePerLoopMaxRows));
1396	        tilingData->set_perCoreLoops((perCoreRows + basePerLoopMaxRows - 1) / basePerLoopMaxRows);
1397	
1398	        tilingData->set_lastCorePerLoopRows(std::min(lastCoreRows, basePerLoopMaxRows));
1399	        tilingData->set_lastCoreLastLoopRows(GetPerOrLastValue(lastCoreRows, basePerLoopMaxRows));
1400	        tilingData->set_lastCoreLoops((lastCoreRows + basePerLoopMaxRows - 1) / basePerLoopMaxRows);
1401	    }
1402	}
1403	
1404	void MoeInitRountingV3TilingBase::SetGatherTilingData(
1405	    MoeV3SrcToDstCapacityComputeTilingData* tilingData, int64_t perCoreRows, int64_t lastCoreRows, int64_t cols)
1406	{
1407	    tilingData->set_perCorePerLoopRows(perCoreRows);
1408	    tilingData->set_perCoreLastLoopRows(perCoreRows);
1409	    tilingData->set_lastCorePerLoopRows(lastCoreRows);
1410	    tilingData->set_lastCoreLastLoopRows(lastCoreRows);
1411	    tilingData->set_perCoreLoops(1);
1412	    tilingData->set_lastCoreLoops(1);
1413	    tilingData->set_perLoopCols(cols);
1414	    tilingData->set_lastLoopCols(cols);
1415	    tilingData->set_colLoops(1);
1416	}
1417	
1418	void MoeInitRountingV3TilingBase::SetGatherTilingDataCols(
1419	    MoeV3SrcToDstCapacityComputeTilingData* tilingData, int64_t baseMaxCols, int64_t cols)
1420	{
1421	    tilingData->set_perLoopCols(std::min(baseMaxCols, cols));
1422	    tilingData->set_lastLoopCols(GetPerOrLastValue(cols, baseMaxCols));
1423	    tilingData->set_colLoops(baseMaxCols == 0 ? 0 : (cols + baseMaxCols - 1) / baseMaxCols);
1424	}
1425	
1426	void MoeInitRountingV3TilingBase::SetGatherTilingDataRows(
1427	    MoeV3SrcToDstCapacityComputeTilingData* tilingData, int64_t perCoreRows, int64_t lastCoreRows,
1428	    int64_t basePerLoopMaxRows)
1429	{
1430	    tilingData->set_perCorePerLoopRows(std::min(perCoreRows, basePerLoopMaxRows));
1431	    tilingData->set_perCoreLastLoopRows(GetPerOrLastValue(perCoreRows, basePerLoopMaxRows));
1432	    tilingData->set_perCoreLoops(
1433	        basePerLoopMaxRows == 0 ? 0 : (perCoreRows + basePerLoopMaxRows - 1) / basePerLoopMaxRows);
1434	
1435	    tilingData->set_lastCorePerLoopRows(std::min(lastCoreRows, basePerLoopMaxRows));
1436	    tilingData->set_lastCoreLastLoopRows(GetPerOrLastValue(lastCoreRows, basePerLoopMaxRows));
1437	    tilingData->set_lastCoreLoops(
1438	        basePerLoopMaxRows == 0 ? 0 : (lastCoreRows + basePerLoopMaxRows - 1) / basePerLoopMaxRows);
1439	}
1440	
1441	void MoeInitRountingV3TilingBase::Tiling4SrcToDstDropPadDynamicCompute()
1442	{
1443	    auto tilingData = &moeInitRoutingV3TilingData.srcToDstDropPadDynamicParamsOp;
1444	
1445	    int64_t perCoreRows = OpsBaseCeilDiv(totalLength_, aivNum);
1446	    if (perCoreRows <= 0) {
1447	        tilingData->set_needCoreNum(0);
1448	        return;
1449	    }
1450	    tilingData->set_needCoreNum(OpsBaseCeilDiv(totalLength_, perCoreRows));
1451	    int64_t cols = moeInitRoutingV3TilingData.get_cols();
1452	    tilingData->set_perCoreRows(perCoreRows);
1453	    int64_t lastCoreRows = totalLength_ - perCoreRows * (tilingData->get_needCoreNum() - 1);
1454	    tilingData->set_lastCoreRows(lastCoreRows);
1455	
1456	    int64_t rowSize = AlignBytes(perCoreRows, static_cast<int64_t>(sizeof(int32_t))) * NUM_FOUR;
1457	    int64_t colSize = AlignBytes(cols, static_cast<int64_t>(sizeof(int8_t))) * DYNAMIC_QUANT_SRC_TO_DST_BUFFER;
1458	    int64_t scaleSize = DYNAMIC_QUANT_SCALE_SIZE_64;
1459	    if (rowSize + colSize + scaleSize < static_cast<int64_t>(aicoreParams_.ubSize)) {
1460	        SetGatherTilingData(tilingData, perCoreRows, lastCoreRows, cols);
1461	    } else {
1462	        int64_t baseMaxCols = MAX_COLS_DYNAMIC_QUANT;
1463	        int64_t totalColSize =
1464	            AlignBytes(baseMaxCols, static_cast<int64_t>(sizeof(int8_t))) * DYNAMIC_QUANT_SRC_TO_DST_BUFFER;
1465	        int64_t ubSize = static_cast<int64_t>(aicoreParams_.ubSize);
1466	        int64_t basePerLoopMaxRows = AlignOneBlockByteCeil((ubSize - totalColSize - scaleSize) / SIZE_INT32) / NUM_FOUR;
1467	        if (cols < MAX_COLS_DYNAMIC_QUANT) {
1468	            basePerLoopMaxRows = AlignOneBlockByteCeil((ubSize - colSize - scaleSize) / SIZE_INT32) / NUM_FOUR;
1469	        } else if (perCoreRows < basePerLoopMaxRows) {
1470	            baseMaxCols = AlignOneBlockByteCeil(ubSize - rowSize - scaleSize) / DYNAMIC_QUANT_SRC_TO_DST_BUFFER;
1471	        }
1472	        SetGatherTilingDataCols(tilingData, baseMaxCols, cols);
1473	        SetGatherTilingDataRows(tilingData, perCoreRows, lastCoreRows, basePerLoopMaxRows);
1474	    }
1475	}
1476	
1477	void MoeInitRountingV3TilingBase::Tiling4SrcToDstCompute()
1478	{
1479	    auto tilingData = &moeInitRoutingV3TilingData.srcToDstComputeParamsOp;
1480	
1481	    int64_t useCore = aivNum;
1482	    // ubsize减去32B对齐保留空间
1483	    int64_t remainUbSize = aicoreParams_.ubSize - ASSIST_NUM * sizeof(int32_t) - ONE_BLOCK_BYTE * (ASSIST_NUM + 1);
1484	    int64_t perLoopMaxElements = remainUbSize / (ONE_BLOCK_BYTE + SIZE_INT32);
1485	    int64_t perCoreElements = OpsBaseCeilDiv(totalLength_, useCore);
1486	    if (perCoreElements <= 0) {
1487	        tilingData->set_needCoreNum(0);
1488	        return;
1489	    }
1490	    int64_t needCoreNum = OpsBaseCeilDiv(totalLength_, perCoreElements);
1491	    tilingData->set_needCoreNum(needCoreNum);
1492	    int64_t lastCoreElements = totalLength_ - perCoreElements * (needCoreNum - 1);
1493	
1494	    tilingData->set_perCoreElements(perCoreElements);
1495	    tilingData->set_lastCoreElements(lastCoreElements);
1496	    int64_t perCoreLoops = OpsBaseCeilDiv(perCoreElements, perLoopMaxElements);
1497	    int64_t perCorePerLoopElements = OpsBaseCeilDiv(perCoreElements, perCoreLoops);
1498	    int64_t perCoreLastLoopElements = perCoreElements - (perCoreLoops - 1) * perCorePerLoopElements;
1499	
1500	    int64_t lastCoreLoops = OpsBaseCeilDiv(lastCoreElements, perLoopMaxElements);
1501	    int64_t lastCorePerLoopElements = OpsBaseCeilDiv(lastCoreElements, lastCoreLoops);
1502	    int64_t lastCoreLastLoopElements = lastCoreElements - (lastCoreLoops - 1) * lastCorePerLoopElements;
1503	
1504	    tilingData->set_perCoreLoops(perCoreLoops);
1505	    tilingData->set_perCorePerLoopElements(perCorePerLoopElements);
1506	    tilingData->set_perCoreLastLoopElements(perCoreLastLoopElements);
1507	    tilingData->set_lastCoreLoops(lastCoreLoops);
1508	    tilingData->set_lastCorePerLoopElements(lastCorePerLoopElements);
1509	    tilingData->set_lastCoreLastLoopElements(lastCoreLastLoopElements);
1510	}
1511	
1512	void MoeInitRountingV3TilingBase::Tiling4GatherOutCompute()
1513	{
1514	    auto tilingData = &moeInitRoutingV3TilingData.gatherOutComputeParamsOp;
1515	    int64_t perCoreIndicesElements = OpsBaseCeilDiv(totalLength_, aivNum);
1516	    if (perCoreIndicesElements <= 0) {
1517	        tilingData->set_needCoreNum(0);
1518	        return;
1519	    }
1520	    int64_t needCoreNum = OpsBaseCeilDiv(totalLength_, perCoreIndicesElements);
1521	    int64_t lastCoreIndicesElements = totalLength_ - (needCoreNum - 1) * perCoreIndicesElements;
1522	
1523	    int64_t perLoopCols = moeInitRoutingV3TilingData.get_cols();
1524	    int64_t colMultiple = NUM_TWO * inuptXDtypeSize_;
1525	    int64_t rowMultiple = NUM_TWO;
1526	    if (quantMode_ == DYNAMIC_QUANT) {
1527	        colMultiple = DYNAMIC_QUANT_COLS_BUFFER;
1528	        rowMultiple = NUM_FOUR;
1529	    }
1530	    if (quantMode_ == STATIC_QUANT) {
1531	        colMultiple = SIZE_INT8 * NUM_TWO + SIZE_FP32 + SIZE_INT16 + inuptXDtypeSize_ * NUM_TWO;
1532	        rowMultiple = NUM_TWO;
1533	    }
1534	    int64_t perLoopMaxIndicesElements =
1535	        (static_cast<int64_t>(aicoreParams_.ubSize) - Align(perLoopCols, inuptXDtypeSize_) * colMultiple -
1536	         ONE_BLOCK_BYTE * NUM_TWO) /
1537	        rowMultiple / static_cast<int64_t>(sizeof(int32_t));
1538	    while (perLoopMaxIndicesElements <= 0) {
1539	        perLoopCols = OpsBaseCeilDiv(perLoopCols, NUM_TWO);
1540	        perLoopMaxIndicesElements = (static_cast<int64_t>(aicoreParams_.ubSize) -
1541	                                     Align(perLoopCols, inuptXDtypeSize_) * colMultiple - ONE_BLOCK_BYTE * NUM_TWO) /
1542	                                    rowMultiple / static_cast<int64_t>(sizeof(int32_t));
1543	        OP_LOGI(
1544	            context_, "perLoopCols is: %ld, perLoopMaxIndicesElements is: %ld", perLoopCols, perLoopMaxIndicesElements);
1545	    }
1546	    int64_t colsLoops = OpsBaseCeilDiv(moeInitRoutingV3TilingData.get_cols(), perLoopCols);
1547	    int64_t lastLoopCols = moeInitRoutingV3TilingData.get_cols() - (colsLoops - 1) * perLoopCols;
1548	    tilingData->set_needCoreNum(needCoreNum);
1549	    tilingData->set_perCoreIndicesElements(perCoreIndicesElements);
1550	    tilingData->set_lastCoreIndicesElements(lastCoreIndicesElements);
1551	    tilingData->set_colsLoops(colsLoops);
1552	    tilingData->set_perLoopCols(perLoopCols);
1553	    tilingData->set_lastLoopCols(lastLoopCols);
1554	
1555	    int64_t perCorePerLoopIndicesElements = std::min(perLoopMaxIndicesElements, perCoreIndicesElements);
1556	    int64_t perCoreIndicesLoops = OpsBaseCeilDiv(perCoreIndicesElements, perCorePerLoopIndicesElements);
1557	    int64_t perCoreLastLoopIndicesElements =
1558	        perCoreIndicesElements - (perCoreIndicesLoops - 1) * perCorePerLoopIndicesElements;
1559	    tilingData->set_perCoreIndicesLoops(perCoreIndicesLoops);
1560	    tilingData->set_perCorePerLoopIndicesElements(perCorePerLoopIndicesElements);
1561	    tilingData->set_perCoreLastLoopIndicesElements(perCoreLastLoopIndicesElements);
1562	
1563	    int64_t lastCorePerLoopIndicesElements = std::min(perLoopMaxIndicesElements, lastCoreIndicesElements);
1564	    int64_t lastCoreIndicesLoops = OpsBaseCeilDiv(lastCoreIndicesElements, lastCorePerLoopIndicesElements);
1565	    int64_t lastCoreLastLoopIndicesElements =
1566	        lastCoreIndicesElements - (lastCoreIndicesLoops - 1) * lastCorePerLoopIndicesElements;
1567	    tilingData->set_lastCoreIndicesLoops(lastCoreIndicesLoops);
1568	    tilingData->set_lastCorePerLoopIndicesElements(lastCorePerLoopIndicesElements);
1569	    tilingData->set_lastCoreLastLoopIndicesElements(lastCoreLastLoopIndicesElements);
1570	
1571	    OP_LOGI(
1572	        context_,
1573	        "GatherOut Tilingdata, needCoreNum is: %ld, perCoreIndicesElements is: %ld, lastCoreIndicesElements is: %ld, "
1574	        "colsLoops is: %ld, perLoopCols is: %ld, lastLoopCols is: %ld, perCoreIndicesLoops is: %ld, "
1575	        "perCorePerLoopIndicesElements is: %ld, perCoreLastLoopIndicesElements is: %ld, lastCoreIndicesLoops is: "
1576	        "%ld, lastCorePerLoopIndicesElements is: "
1577	        "%ld, lastCoreLastLoopIndicesElements is: %ld.",
1578	        needCoreNum, perCoreIndicesElements, lastCoreIndicesElements, colsLoops, perLoopCols, lastLoopCols,
1579	        perCoreIndicesLoops, perCorePerLoopIndicesElements, perCoreLastLoopIndicesElements, lastCoreIndicesLoops,
1580	        lastCorePerLoopIndicesElements, lastCoreLastLoopIndicesElements);
1581	}
1582	
1583	REGISTER_OPS_TILING_TEMPLATE(
1584	    AiInfraMoeInitRoutingV3, MoeInitRountingV3TilingBase, 10000); // If not 950, fallback to this.
1585	} // namespace optiling
