inline static int64_t CeilLog4(const int64_t x)
{
    return static_cast<int64_t>(std::ceil(std::log(x) / std::log(NUM_FOUR)));
}

inline static int64_t Align(const int64_t elementNum, const int64_t bytes)
{
    if (bytes == 0) {
        return 0;
    }
    return (elementNum * bytes + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE / bytes;
}

inline static int64_t AlignBytes(const int64_t elementNum, const int64_t bytes)
{
    return (elementNum * bytes + ONE_BLOCK_BYTE - 1) / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
}

inline static int64_t GetPerOrLastValue(const int64_t x, const int64_t y)
{
    if (y == 0) {
        return 0;
    }
    return x <= y ? x : x % y;
}

inline static int64_t AlignOneBlockByteCeil(const int64_t x)
{
    return x / ONE_BLOCK_BYTE * ONE_BLOCK_BYTE;
}

template <typename T>
inline T OpsBaseCeilDiv(T a, T b)
{
    if (b == 0) {
        return 0;
    }
    return (a + b - 1) / b;
}

template <typename T>
inline T OpsBaseCeilAlign(T a, T b)
{
    return OpsBaseCeilDiv(a, b) * b;
}

inline std::string OpsBaseToString(const gert::Shape& shape)
{
    std::ostringstream oss;
    oss << "(";
    for (size_t i = 0; i < shape.GetDimNum(); ++i) {
        if (i > 0)
            oss << ", ";
        oss << shape.GetDim(i);
    }
    oss << ")";
    return oss.str();
}

