37	
38	/*
39	 * 高性能模板, 全在模板
40	 */
41	#define MOE_INIT_ROUTING_V3_PERFORMANCE 2000000
42	#define UNQUANTIZED_FULLLOAD 2100000
43	#define STATIC_QUANT_FULLLOAD 2200000
44	#define DYNAMIC_QUANT_GATHER_NO_SCALE_FULLLOAD 2300000
45	#define DYNAMIC_QUANT_GATHER_1H_DIM_SCALE_FULLLOAD 2301000
46	#define DYNAMIC_QUANT_GATHER_EH_SCALE_FULLLOAD 2302000
47	#define DYNAMIC_QUANT_SCATTER_NO_SCALE_FULLLOAD 2310000
48	#define DYNAMIC_QUANT_SCATTER_1H_SCALE_FULLLOAD 2311000
49	#define DYNAMIC_QUANT_SCATTER_EH_SCALE_FULLLOAD 2312000
50	
51	/*
52	 * 非量化、无Gather、非Drop/Pad
53	 */
54	#define MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_NODROP 1000000    // 无Gather单核排序、非量化、GATHER索引
55	#define MOE_INIT_ROUTING_V3_SORTONECORE_SCATTER_NODROP 1001000   // 无Gather单核排序、非量化、SCATTER索引
56	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_NODROP 1100000  // 无Gather多核排序、非量化、GATHER索引
57	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_SCATTER_NODROP 1101000 // 无Gather多核排序、非量化、SCATTER索引
58	
59	/*
60	 * 动态量化、无Gather、非Drop/Pad
61	 */
62	#define MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_NODROP 1020000    // 单核排序、动态量化、GATHER索引
63	#define MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_SCATTER_NODROP 1021000   // 单核排序、动态量化、SCATTER索引
64	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_NODROP 1120000  // 多核排序、动态量化、GATHER索引
65	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_SCATTER_NODROP 1121000 // 多核排序、动态量化、GATHER索引
66	
67	/*
68	 * 静态量化、无Gather、非Drop/Pad
69	 */
70	#define MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_NODROP 1010000    // 单核排序、静态量化、GATHER索引
71	#define MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_SCATTER_NODROP 1011000   // 单核排序、静态量化、SCATTER索引
72	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_NODROP 1110000  // 多核排序、静态量化、GATHER索引
73	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_SCATTER_NODROP 1111000 // 多核排序、静态量化、GATHER索引
74	
75	/*
76	 * Drop/Pad
77	 */
78	#define MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_DROP 1000100                // 单核排序、非量化、GATHER索引
79	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_DROP 1100100              // 多核排序、非量化、GATHER索引
80	#define MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_DROP 1020100   // 单核排序、动态量化、GATHER索引
81	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_DROP 1120100 // 多核排序、动态量化、GATHER索引
82	#define MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_DROP 1010100          // 单核排序、静态量化、GATHER索引
83	#define MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_DROP 1110100        // 多核排序、静态量化、GATHER索引
84	
85	/*
86	 * 非量化、有Gather
87	 */
88	#define MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_GATHER 1200000    // 单核Gather->单核或多核排序、非量化、GATHER索引
89	#define MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER 1201000   // 单核Gather->单核或多核排序、非量化、SCATTER索引
90	#define MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_GATHER 1300000  // 多核Gather->多核排序、非量化、GATHER索引
91	#define MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER 1301000 // 多核Gather->多核排序、非量化、SCATTER索引
92	
93	#define EMPTY_TENSOR 3000000
94	
95	using namespace AscendC;
96	using namespace MoeInitRoutingV3;
97	extern "C" __global__ __aicore__ void ai_infra_moe_init_routing_v3(
98	    GM_ADDR x, GM_ADDR expertIdx, GM_ADDR scale, GM_ADDR offset, GM_ADDR expandedX, GM_ADDR expandedRowIdx,
99	    GM_ADDR expertTokensCountOrCumsum, GM_ADDR expandedScale, GM_ADDR workspace, GM_ADDR tiling)
100	{
101	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
102	    if (g_coreType == AIC) {
103	        return;
104	    }
105	
106	    GET_TILING_DATA(tilingData, tiling);
107	    if (workspace == nullptr) {
108	        return;
109	    }
110	
111	    GM_ADDR userWS = GetUserWorkspace(workspace);
112	    if (userWS == nullptr) {
113	        return;
114	    }
115	
116	    auto t = &tilingData;
117	
118	    if (TILING_KEY_IS(EMPTY_TENSOR)) {
119	        if (GetBlockIdx() != 0) {
120	            return;
121	        }
122	        if (t->expertTokensNumFlag) {
123	            GlobalTensor<int64_t> expertTokensCountGm;
124	            TBuf<TPosition::VECCALC> zeroBuf;
125	            TPipe pipe;
126	            int32_t expertCountElements = t->expertCountElements;
127	            expertTokensCountGm.SetGlobalBuffer((__gm__ int64_t*)expertTokensCountOrCumsum, expertCountElements);
128	            pipe.InitBuffer(zeroBuf, AlignBytes(expertCountElements, sizeof(int64_t)));
129	
130	            LocalTensor<int64_t> zeroLocal = zeroBuf.Get<int64_t>();
131	            Duplicate<int32_t>(
132	                zeroLocal.ReinterpretCast<int32_t>(), static_cast<int32_t>(0),
133	                static_cast<int32_t>(Align(expertCountElements, static_cast<int32_t>(sizeof(int64_t))) * 2));
134	            DataCopyExtParams dataCopyParams = {
135	                1, static_cast<uint32_t>(expertCountElements * sizeof(int64_t)), 0, 0, 0};
136	            DataCopyPad(expertTokensCountGm, zeroLocal, dataCopyParams);
137	            pipe.Destroy();
138	        }
139	        return;
140	    }
141	
142	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_PERFORMANCE)) {
143	        TPipe fullLoadPipe;
144	        MoeV3FullLoad op;
145	        op.Init(
146	            x, expertIdx, scale, offset, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, t,
147	            &fullLoadPipe);
148	        op.Process();
149	        fullLoadPipe.Destroy();
150	        return;
151	    }
152	
153	    if (TILING_KEY_IS(DYNAMIC_QUANT_GATHER_NO_SCALE_FULLLOAD)) {
154	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
155	            TPipe fullLoadPipe;
156	            MoeV3FullLoadDynamicQuant<DTYPE_X, GATHER, NO_SCALE> op;
157	            op.Init(
158	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
159	                &fullLoadPipe);
160	            op.Process();
161	            fullLoadPipe.Destroy();
162	        }
163	        return;
164	    }
165	
166	    if (TILING_KEY_IS(DYNAMIC_QUANT_GATHER_1H_DIM_SCALE_FULLLOAD)) {
167	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
168	            TPipe fullLoadPipe;
169	            MoeV3FullLoadDynamicQuant<DTYPE_X, GATHER, SCALE_1H> op;
170	            op.Init(
171	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
172	                &fullLoadPipe);
173	            op.Process();
174	            fullLoadPipe.Destroy();
175	        }
176	        return;
177	    }
178	
179	    if (TILING_KEY_IS(DYNAMIC_QUANT_GATHER_EH_SCALE_FULLLOAD)) {
180	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
181	            TPipe fullLoadPipe;
182	            MoeV3FullLoadDynamicQuant<DTYPE_X, GATHER, SCALE_EH> op;
183	            op.Init(
184	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
185	                &fullLoadPipe);
186	            op.Process();
187	            fullLoadPipe.Destroy();
188	        }
189	        return;
190	    }
191	
192	    if (TILING_KEY_IS(DYNAMIC_QUANT_SCATTER_NO_SCALE_FULLLOAD)) {
193	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
194	            TPipe fullLoadPipe;
195	            MoeV3FullLoadDynamicQuant<DTYPE_X, SCATTER, NO_SCALE> op;
196	            op.Init(
197	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
198	                &fullLoadPipe);
199	            op.Process();
200	            fullLoadPipe.Destroy();
201	        }
202	        return;
203	    }
204	
205	    if (TILING_KEY_IS(DYNAMIC_QUANT_SCATTER_1H_SCALE_FULLLOAD)) {
206	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
207	            TPipe fullLoadPipe;
208	            MoeV3FullLoadDynamicQuant<DTYPE_X, SCATTER, SCALE_1H> op;
209	            op.Init(
210	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
211	                &fullLoadPipe);
212	            op.Process();
213	            fullLoadPipe.Destroy();
214	        }
215	        return;
216	    }
217	
218	    if (TILING_KEY_IS(DYNAMIC_QUANT_SCATTER_EH_SCALE_FULLLOAD)) {
219	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
220	            TPipe fullLoadPipe;
221	            MoeV3FullLoadDynamicQuant<DTYPE_X, SCATTER, SCALE_EH> op;
222	            op.Init(
223	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
224	                &fullLoadPipe);
225	            op.Process();
226	            fullLoadPipe.Destroy();
227	        }
228	        return;
229	    }
230	
231	    if (TILING_KEY_IS(UNQUANTIZED_FULLLOAD)) {
232	        TPipe fullLoadPipe;
233	        MoeV3FullLoadUnquantized<DTYPE_X> op;
234	        op.Init(
235	            x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
236	            &fullLoadPipe);
237	        op.Process();
238	        fullLoadPipe.Destroy();
239	        return;
240	    }
241	
242	    if (TILING_KEY_IS(STATIC_QUANT_FULLLOAD)) {
243	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
244	            TPipe fullLoadPipe;
245	            MoeV3FullLoadStaticQuant<DTYPE_X> op;
246	            op.Init(
247	                x, expertIdx, scale, offset, expandedX, expandedRowIdx, expertTokensCountOrCumsum, userWS, t,
248	                &fullLoadPipe);
249	            op.Process();
250	            fullLoadPipe.Destroy();
251	        }
252	        return;
253	    }
254	
255	    // Counting sort optimization: intercept gather-first four tiling keys
256	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_GATHER) ||
257	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER)) {
258	        bool useCountingSort =
259	            (t->dropPadMode == 0 && t->expertTokensNumType == EXERPT_TOKENS_COUNT && t->quantMode == -1 &&
260	             t->actualExpertNum <= 128 &&
261	             !(t->n <= COUNTING_SORT_THRESHOLD && t->rowIdxType == SCATTER &&
262	               (t->expertEnd - t->expertStart) <= PERFORMANCE_MODE_RANGE_MAX));
263	        if (useCountingSort) {
264	            // FullLoad counting sort (decode small T)
265	            TPipe countSortPipe;
266	            MoeV3FullLoadCutOriginT<DTYPE_X> op;
267	            op.Init(
268	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
269	                &countSortPipe);
270	            op.Process();
271	            countSortPipe.Destroy();
272	            return;
273	        }
274	    }
275	
276	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_GATHER) ||
277	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER)) {
278	        bool useCountingSort =
279	            (t->dropPadMode == 0 && t->expertTokensNumType == EXERPT_TOKENS_COUNT && t->quantMode == -1 &&
280	             t->actualExpertNum <= 128 &&
281	             !(t->n <= COUNTING_SORT_THRESHOLD && t->rowIdxType == SCATTER &&
282	               (t->expertEnd - t->expertStart) <= PERFORMANCE_MODE_RANGE_MAX));
283	        if (useCountingSort) {
284	            // Non-FullLoad counting sort (prefill large T)
285	            TPipe countSortPipe;
286	            MoeV3CutOriginT<DTYPE_X> op;
287	            op.Init(
288	                x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
289	                &countSortPipe);
290	            op.Process();
291	            countSortPipe.Destroy();
292	            return;
293	        }
294	    }
295	
296	    // Fall through to original gather-first flow if counting sort not applicable
297	
298	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_GATHER) ||
299	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER)) {
300	        TPipe sortActualExpertPipe;
301	        MoeSortActualExpert<DTYPE_X> op;
302	        bool isFinished = false;
303	        op.Init(
304	            x, expertIdx, scale, expandedX, expandedRowIdx, expertTokensCountOrCumsum, expandedScale, userWS, t,
305	            &sortActualExpertPipe);
306	        isFinished = op.Process();
307	        sortActualExpertPipe.Destroy();
308	        if (isFinished) {
309	            return;
310	        }
311	    }
312	
313	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_GATHER) ||
314	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER)) {
315	        TPipe gatherSortMultiCorePipe;
316	        MoeGatherSortMultiCore op;
317	        op.Init(expertIdx, expandedRowIdx, userWS, t, &gatherSortMultiCorePipe);
318	        op.Process();
319	        gatherSortMultiCorePipe.Destroy();
320	    }
321	
322	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_GATHER) ||
323	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER) ||
324	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_GATHER) ||
325	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER)) {
326	        TPipe mergeSortMultiCorePipe;
327	        MoeSortMultiCorePerformance op;
328	        op.Init(expandedRowIdx, userWS, t, &mergeSortMultiCorePipe);
329	        op.Process();
330	        mergeSortMultiCorePipe.Destroy();
331	    }
332	
333	    TPipe sortPipe;
334	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_NODROP) ||
335	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_SCATTER_NODROP) ||
336	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_NODROP) ||
337	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_SCATTER_NODROP) ||
338	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_NODROP) ||
339	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_SCATTER_NODROP) ||
340	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_DROP) ||
341	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_DROP) ||
342	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_DROP)) {
343	        // 单核排序
344	        MoeSortOneCore op;
345	        op.Init(expertIdx, expandedRowIdx, userWS, t, &sortPipe);
346	        op.Process();
347	    } else if (
348	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_NODROP) ||
349	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_SCATTER_NODROP) ||
350	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_SCATTER_NODROP) ||
351	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_NODROP) ||
352	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_SCATTER_NODROP) ||
353	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_NODROP) ||
354	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_DROP) ||
355	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_DROP) ||
356	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_DROP)) {
357	        // 多核排序
358	        MoeSortMultiCore op;
359	        op.Init(expertIdx, expandedRowIdx, userWS, t, &sortPipe);
360	        op.Process();
361	    }
362	    sortPipe.Destroy();
363	
364	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_GATHER) ||
365	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER) ||
366	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_GATHER) ||
367	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER)) {
368	        TPipe histogramPipe;
369	        if (t->expertTokensNumType == CUMSUM_MODE) {
370	            ExpertTokensCount<CUMSUM_MODE> countOp;
371	            countOp.Init<true>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
372	            countOp.Process();
373	            histogramPipe.Destroy();
374	        } else if (t->expertTokensNumType == COUNT_MODE) {
375	            ExpertTokensCount<COUNT_MODE> countOp;
376	            countOp.Init<true>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
377	            countOp.Process();
378	            histogramPipe.Destroy();
379	        } else {
380	            ExpertTokensCount<KEY_VALUE_MODE> countOp;
381	            countOp.Init<true>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
382	            countOp.Process();
383	            histogramPipe.Destroy();
384	        }
385	
386	    } else {
387	        if (t->dropPadMode == 1 || t->ep == 1 || t->expertTokensNumFlag != EXERPT_TOKENS_NONE) {
388	            TPipe histogramPipe;
389	            if (t->expertTokensNumType == CUMSUM_MODE) {
390	                ExpertTokensCount<CUMSUM_MODE> countOp;
391	                countOp.Init<false>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
392	                countOp.Process();
393	                histogramPipe.Destroy();
394	            } else if (t->expertTokensNumType == COUNT_MODE) {
395	                ExpertTokensCount<COUNT_MODE> countOp;
396	                countOp.Init<false>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
397	                countOp.Process();
398	                histogramPipe.Destroy();
399	            } else {
400	                ExpertTokensCount<KEY_VALUE_MODE> countOp;
401	                countOp.Init<false>(expandedRowIdx, expertTokensCountOrCumsum, userWS, t, &histogramPipe);
402	                countOp.Process();
403	                histogramPipe.Destroy();
404	            }
405	        }
406	    }
407	
408	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_DROP) ||
409	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_DROP)) {
410	        TPipe rowIdxGatherDropPadPipe;
411	        MoeV3SrcToDstWithCapacity<DTYPE_X, MoeInitRoutingV3TilingData> rowIdxGatherDropPadOp;
412	        rowIdxGatherDropPadOp.Init(expandedRowIdx, expandedX, expandedScale, userWS, t, &rowIdxGatherDropPadPipe);
413	        rowIdxGatherDropPadOp.Process();
414	        rowIdxGatherDropPadPipe.Destroy();
415	    } else if (
416	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_DROP) ||
417	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_DROP)) {
418	        TPipe rowIdxGatherDropPadPipe;
419	        MoeV3SrcToDstWithCapacity<int8_t, MoeInitRoutingV3TilingData> rowIdxGatherDropPadOp;
420	        rowIdxGatherDropPadOp.Init(expandedRowIdx, expandedX, expandedScale, userWS, t, &rowIdxGatherDropPadPipe);
421	        rowIdxGatherDropPadOp.Process();
422	        rowIdxGatherDropPadPipe.Destroy();
423	    } else if (
424	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_DROP) ||
425	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_DROP)) {
426	        // 动态量化、Drop/Pad
427	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
428	            TPipe gatherPipe;
429	            MoeV3SrcToDstAndGather<DTYPE_X, MoeInitRoutingV3TilingData> gatherDroppadDynamicQuantOp;
430	            gatherDroppadDynamicQuantOp.Init(
431	                x, scale, expandedRowIdx, expandedX, expandedScale, userWS, t, &gatherPipe);
432	            gatherDroppadDynamicQuantOp.Process();
433	            gatherPipe.Destroy();
434	        }
435	    } else {
436	        TPipe rowIdxPipe;
437	        RowIdxGather rowIdxGatherOp;
438	        rowIdxGatherOp.Init(expandedRowIdx, userWS, t, &rowIdxPipe);
439	        rowIdxGatherOp.Process();
440	        rowIdxPipe.Destroy();
441	    }
442	
443	    if (TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_NODROP) ||
444	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_SCATTER_NODROP) ||
445	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_NODROP) ||
446	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_SCATTER_NODROP) ||
447	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTONECORE_SCATTER) ||
448	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_GATHER_SORTMULTICORE_SCATTER)) {
449	        // 非量化、非Drop/Pad
450	        TPipe gatherPipe;
451	        if (t->ep == 1) {
452	            MoeGatherOut<DTYPE_X, 1> gatherOp;
453	            gatherOp.Init(x, scale, userWS, expandedRowIdx, expandedX, expandedScale, t, &gatherPipe);
454	            gatherOp.Process();
455	            gatherPipe.Destroy();
456	        } else {
457	            MoeGatherOut<DTYPE_X, 0> gatherOp;
458	            gatherOp.Init(x, scale, userWS, expandedRowIdx, expandedX, expandedScale, t, &gatherPipe);
459	            gatherOp.Process();
460	            gatherPipe.Destroy();
461	        }
462	
463	    } else if (
464	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_SCATTER_NODROP) ||
465	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_DYNAMICQUANT_GATHER_NODROP) ||
466	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_SCATTER_NODROP) ||
467	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_DYNAMICQUANT_GATHER_NODROP)) {
468	        // 动态量化、非Drop/Pad
469	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
470	            TPipe gatherPipe;
471	            if (t->ep == 0 and t->smoothType != SCALE_EH) {
472	                MoeGatherOutDynamicQuant<DTYPE_X, GATHER> gatherDynamicQuantOp;
473	                gatherDynamicQuantOp.Init(x, scale, userWS, expandedRowIdx, expandedX, expandedScale, t, &gatherPipe);
474	                gatherDynamicQuantOp.Process();
475	                gatherPipe.Destroy();
476	            } else {
477	                MoeGatherOutDynamicQuant<DTYPE_X, SCATTER> gatherDynamicQuantOp;
478	                gatherDynamicQuantOp.Init(x, scale, userWS, expandedRowIdx, expandedX, expandedScale, t, &gatherPipe);
479	                gatherDynamicQuantOp.Process();
480	                gatherPipe.Destroy();
481	            }
482	        }
483	    } else if (
484	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_SCATTER_NODROP) ||
485	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_NODROP) ||
486	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_SCATTER_NODROP) ||
487	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_NODROP)) {
488	        // 静态量化、非Drop/Pad
489	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
490	            TPipe gatherPipe;
491	            if (t->ep == 1) {
492	                MoeGatherOutQuant<DTYPE_X, 1> gatherStaticQuantOp;
493	                gatherStaticQuantOp.Init(x, scale, offset, expandedRowIdx, expandedX, userWS, t, &gatherPipe);
494	                gatherStaticQuantOp.Process();
495	                gatherPipe.Destroy();
496	            } else {
497	                MoeGatherOutQuant<DTYPE_X, 0> gatherStaticQuantOp;
498	                gatherStaticQuantOp.Init(x, scale, offset, expandedRowIdx, expandedX, userWS, t, &gatherPipe);
499	                gatherStaticQuantOp.Process();
500	                gatherPipe.Destroy();
501	            }
502	        }
503	    } else if (
504	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_GATHER_DROP) ||
505	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_GATHER_DROP)) {
506	        // 非量化、Drop/Pad
507	        TPipe gatherPipe;
508	        MoeGatherOutDroppad<DTYPE_X> gatherDroppadOp;
509	        gatherDroppadOp.Init(x, scale, expandedRowIdx, expandedX, expandedScale, userWS, t, &gatherPipe);
510	        gatherDroppadOp.Process();
511	        gatherPipe.Destroy();
512	    } else if (
513	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTONECORE_QUANT_GATHER_DROP) ||
514	        TILING_KEY_IS(MOE_INIT_ROUTING_V3_SORTMULTICORE_QUANT_GATHER_DROP)) {
515	        // 静态量化、Drop/Pad
516	        if constexpr (!IsSameType<DTYPE_X, int8_t>::value) {
517	            TPipe gatherPipe;
518	            MoeGatherDroppadQuant<DTYPE_X> gatherDroppadStaticQuantOp;
519	            gatherDroppadStaticQuantOp.Init(x, scale, offset, expandedRowIdx, expandedX, userWS, t, &gatherPipe);
520	            gatherDroppadStaticQuantOp.Process();
521	            gatherPipe.Destroy();
522	        }
523	    }
524	}

