20	
21	class MoeV3FullLoad {
22	public:
23	    __aicore__ inline MoeV3FullLoad(){};
24	    __aicore__ inline void Init(
25	        GM_ADDR x, GM_ADDR expertIdx, GM_ADDR scale, GM_ADDR offset, GM_ADDR expandedX, GM_ADDR expandedRowIdx,
26	        GM_ADDR expertTokensCountOrCumsum, GM_ADDR expandedScale, const MoeInitRoutingV3TilingData* tilingData,
27	        TPipe* tPipe);
28	    __aicore__ inline void Process();
29	
30	private:
31	    __aicore__ inline void CopyIn();
32	    __aicore__ inline void SortCompute();
33	    __aicore__ inline void ExpertCountCompute();
34	    __aicore__ inline void CopyOutDynamicQuant();
35	
36	private:
37	    int64_t sortNum;
38	
39	    TPipe* pipe;
40	    TQue<QuePosition::VECIN, 1> sortDataCopyInQueue;
41	    TQue<QuePosition::VECOUT, 1> sortDataCopyOutQueue;
42	    TQue<QuePosition::VECOUT, 1> expertTokensCountOrCumsumOutQueue;
43	    TQue<QuePosition::VECIN, 1> smoothInQueue;
44	    TQue<QuePosition::VECIN, 1> inputXInQueue;
45	    TQue<QuePosition::VECOUT, 1> inputXOutQueue;
46	    TQue<QuePosition::VECOUT, 1> scaleOutQueue;
47	    TQue<QuePosition::VECOUT, 1> rowIdxOutQueue;
48	
49	    TBuf<TPosition::VECCALC> tempBuffer;
50	    TBuf<TPosition::VECCALC> sortedBuffer;
51	    TBuf<TPosition::VECCALC> quantTempBuffer;
52	
53	    GlobalTensor<bfloat16_t> inputXGm;
54	    GlobalTensor<float> smoothGm;
55	    GlobalTensor<int8_t> expandedXGm;
56	    GlobalTensor<float> expandedScaleGm;
57	    GlobalTensor<int32_t> expertIdxGm;
58	    GlobalTensor<int32_t> expendedRowIdxGm;
59	    GlobalTensor<int32_t> sortedExpertForSourceRowGm;
60	    GlobalTensor<int32_t> expandDstToSrcRowGm;
61	    GlobalTensor<int32_t> sortedexpertIdxGm;
62	    GlobalTensor<int32_t> expertCountTempGm;
63	    GlobalTensor<int32_t> expandedRowIdxGm;
64	    GlobalTensor<int64_t> expertTokensCountOrCumsumGm;
65	
66	    int64_t blockIdx = 0;
67	    int64_t tileLength;
68	    int64_t bufferNum = 1;
69	    int64_t totalLength;
70	    int64_t n;
71	    int64_t k;
72	    int64_t cols_;
73	    int64_t expertNum_ = 256;
74	    int64_t rowIdxType_;
75	    int64_t kvFactor = 2;
76	    static constexpr int64_t DST_BLK_STRIDE = 1;
77	    static constexpr int64_t DST_REP_STRIDE = 8;
78	};
79	
80	__aicore__ inline void MoeV3FullLoad::CopyIn()
81	{
82	    LocalTensor<int32_t> inLocal = sortDataCopyInQueue.AllocTensor<int32_t>();
83	    DataCopyExtParams dataCopyParams{
84	        static_cast<uint16_t>(1), static_cast<uint32_t>(this->totalLength * sizeof(int32_t)), 0, 0, 0};
85	    DataCopyPadExtParams dataCopyPadParams{false, 0, 0, 0};
86	    DataCopyPad(inLocal[0], expertIdxGm, dataCopyParams, dataCopyPadParams);
87	    LocalTensor<int32_t> rowIdxLocal = inLocal[this->sortNum];
88	    ArithProgression<int32_t>(rowIdxLocal, 0, 1, this->sortNum);
89	    sortDataCopyInQueue.EnQue(inLocal);
90	}
91	
92	__aicore__ inline void MoeV3FullLoad::SortCompute()
93	{
94	    LocalTensor<int32_t> inLocal = sortDataCopyInQueue.DeQue<int32_t>();
95	    LocalTensor<int32_t> expertIdx = inLocal[0];
96	    LocalTensor<float> expertIdxFp32 = expertIdx.ReinterpretCast<float>();
97	    Cast(expertIdxFp32, expertIdx, RoundMode::CAST_ROUND, this->tileLength);
98	    Muls(expertIdxFp32, expertIdxFp32, (float)-1, this->tileLength);
99	    int64_t duplicateNum = this->totalLength % ONE_REPEAT_SORT_NUM;
100	    if (duplicateNum > 0) {
101	        int duplicateIndex = this->totalLength - duplicateNum;
102	        uint64_t mask0 = UINT64_MAX;
103	        mask0 = mask0 << duplicateNum;
104	        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
105	        uint64_t mask[2] = {mask0, 0};
106	        Duplicate(expertIdxFp32[duplicateIndex], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
107	    }
108	
109	    LocalTensor<float> concatLocal;
110	    LocalTensor<float> tempTensor = tempBuffer.Get<float>(GetSortLen<float>(this->sortNum));
111	    Concat(concatLocal, expertIdxFp32, tempTensor, this->sortNum / ONE_REPEAT_SORT_NUM);
112	
113	    LocalTensor<float> sortedLocal = sortedBuffer.Get<float>(GetSortLen<float>(this->sortNum));
114	    LocalTensor<uint32_t> sourceRowLocal;
115	    sourceRowLocal = inLocal[this->sortNum].ReinterpretCast<uint32_t>();
116	    Sort<float, true>(sortedLocal, concatLocal, sourceRowLocal, tempTensor, this->sortNum / ONE_REPEAT_SORT_NUM);
117	
118	    LocalTensor<float> outLocal = sortDataCopyOutQueue.AllocTensor<float>();
119	    LocalTensor<float> sortedExpertForSourceRowLocal = outLocal[0];
120	    LocalTensor<uint32_t> expandDstToSrcRowLocal;
121	    expandDstToSrcRowLocal = outLocal[this->sortNum].ReinterpretCast<uint32_t>();
122	    Extract(sortedExpertForSourceRowLocal, expandDstToSrcRowLocal, sortedLocal, this->sortNum / ONE_REPEAT_SORT_NUM);
123	    Muls(sortedExpertForSourceRowLocal, sortedExpertForSourceRowLocal, (float)-1, this->tileLength);
124	
125	    LocalTensor<int32_t> expertForSourceRowLocalInt32;
126	    expertForSourceRowLocalInt32 = sortedExpertForSourceRowLocal.ReinterpretCast<int32_t>();
127	    Cast(expertForSourceRowLocalInt32, sortedExpertForSourceRowLocal, RoundMode::CAST_ROUND, this->tileLength);
128	    sortDataCopyOutQueue.EnQue<float>(outLocal);
129	    sortDataCopyInQueue.FreeTensor(inLocal);
130	}
131	
132	__aicore__ inline void MoeV3FullLoad::ExpertCountCompute()
133	{
134	    LocalTensor<int32_t> outLocal = sortDataCopyOutQueue.DeQue<int32_t>();
135	    LocalTensor<int32_t> sortedExpertId = outLocal;
136	    LocalTensor<int64_t> expertTokensLocalTensor = expertTokensCountOrCumsumOutQueue.AllocTensor<int64_t>();
137	
138	    int64_t i = 0;
139	    int32_t lastExpertId = sortedExpertId.GetValue(0);
140	    int32_t lastIndex = 0;
141	    int64_t index = 0;
142	    for (i = 1; i < this->totalLength; i++) {
143	        int32_t curExpertId = sortedExpertId.GetValue(i);
144	        if (curExpertId != lastExpertId) {
145	            expertTokensLocalTensor.SetValue(index * kvFactor, lastExpertId);
146	            expertTokensLocalTensor.SetValue(index * kvFactor + 1, i - lastIndex);
147	            index++;
148	            lastIndex = i;
149	            lastExpertId = curExpertId;
150	        }
151	    }
152	    if (i == this->totalLength) {
153	        expertTokensLocalTensor.SetValue(index * kvFactor, lastExpertId);
154	        expertTokensLocalTensor.SetValue(index * kvFactor + 1, i - lastIndex);
155	        index++;
156	    }
157	    // totalLength < 256
158	    expertTokensLocalTensor.SetValue(index * kvFactor, 0);
159	    expertTokensLocalTensor.SetValue(index * kvFactor + 1, 0);
160	    SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
161	
162	    expertTokensCountOrCumsumOutQueue.EnQue<int64_t>(expertTokensLocalTensor);
163	    sortDataCopyOutQueue.EnQue<int32_t>(outLocal);
164	}
165	
166	__aicore__ inline void MoeV3FullLoad::CopyOutDynamicQuant()
167	{
168	    LocalTensor<int64_t> expertTokensLocalTensor = expertTokensCountOrCumsumOutQueue.DeQue<int64_t>();
169	    DataCopyParams intriParams;
170	    intriParams.blockCount = 1;
171	    intriParams.blockLen = expertNum_ * sizeof(int64_t);
172	    DataCopyPad(expertTokensCountOrCumsumGm, expertTokensLocalTensor, intriParams);
173	    expertTokensCountOrCumsumOutQueue.FreeTensor(expertTokensLocalTensor);
174	    LocalTensor<int32_t> outLocal = sortDataCopyOutQueue.DeQue<int32_t>();
175	
176	    // 量化
177	    int64_t expertIdx = outLocal.GetValue(blockIdx);
178	    LocalTensor<bfloat16_t> xInLocal = inputXInQueue.AllocTensor<bfloat16_t>();
179	    LocalTensor<int8_t> xOutLocal = inputXOutQueue.AllocTensor<int8_t>();
180	    LocalTensor<float> smoothLocal = smoothInQueue.AllocTensor<float>();
181	    LocalTensor<float> scaleLocal = scaleOutQueue.AllocTensor<float>();
182	    LocalTensor<float> tempLocal = quantTempBuffer.Get<float>();
183	    DataCopyExtParams copyInParams{1, static_cast<uint32_t>(cols_ * sizeof(bfloat16_t)), 0, 0, 0};
184	    DataCopyExtParams smoothParams{1, static_cast<uint32_t>(cols_ * sizeof(float)), 0, 0, 0};
185	    DataCopyExtParams copyOutParams{1, static_cast<uint32_t>(cols_ * sizeof(int8_t)), 0, 0, 0};
186	    DataCopyPad(xInLocal, inputXGm, copyInParams, {false, 0, 0, 0});
187	    DataCopyPad(smoothLocal, smoothGm[expertIdx * cols_], smoothParams, {false, 0, 0, 0});
188	    smoothInQueue.EnQue<float>(smoothLocal);
189	    smoothLocal = smoothInQueue.DeQue<float>();
190	    Cast(tempLocal, xInLocal, RoundMode::CAST_NONE, cols_);
191	    Mul(smoothLocal, tempLocal, smoothLocal, cols_);
192	    // compute scale
193	    Abs(tempLocal, smoothLocal, cols_);
194	    ReduceMax(scaleLocal, tempLocal, tempLocal, cols_);
195	    float scaleValue = scaleLocal.GetValue(0) / 127.0f;
196	    Duplicate<float>(scaleLocal, scaleValue, DST_REP_STRIDE);
197	    Duplicate<float>(tempLocal, scaleValue, cols_);
198	    // compute quant
199	    Div(tempLocal, smoothLocal, tempLocal, cols_);
200	    Cast(tempLocal.ReinterpretCast<half>(), tempLocal, RoundMode::CAST_ODD, cols_);  // fp32->fp16
201	    Cast(xOutLocal, tempLocal.ReinterpretCast<half>(), RoundMode::CAST_RINT, cols_); // fp16->int8
202	    inputXOutQueue.EnQue<int8_t>(xOutLocal);
203	    xOutLocal = inputXOutQueue.DeQue<int8_t>();
204	    scaleOutQueue.EnQue<float>(scaleLocal);
205	    scaleLocal = scaleOutQueue.DeQue<float>();
206	    DataCopyPad(expandedXGm[blockIdx * cols_], xOutLocal, copyOutParams);
207	    DataCopyPad(expandedScaleGm[blockIdx], scaleLocal, {1, 4, 0, 0, 0});
208	    smoothInQueue.FreeTensor(smoothLocal);
209	    inputXInQueue.FreeTensor(xInLocal);
210	    inputXOutQueue.FreeTensor(xOutLocal);
211	    scaleOutQueue.FreeTensor(scaleLocal);
212	
213	    if (blockIdx == 0) {
214	        intriParams.blockLen = this->totalLength * sizeof(int32_t);
215	        if (rowIdxType_ == 1) {
216	            DataCopyPad(expandedRowIdxGm, outLocal[this->sortNum], intriParams);
217	        } else if (rowIdxType_ == 0) {
218	            LocalTensor rowIdxLocalTensor = rowIdxOutQueue.AllocTensor<int32_t>();
219	            for (int i = 0; i < this->totalLength; i++) {
220	                int32_t dstIdx = outLocal[this->sortNum].GetValue(i);
221	                rowIdxLocalTensor.SetValue(dstIdx, i);
222	            }
223	            SetWaitFlag<HardEvent::S_MTE3>(HardEvent::S_MTE3);
224	            DataCopyPad(expandedRowIdxGm, rowIdxLocalTensor, intriParams);
225	            rowIdxOutQueue.FreeTensor(rowIdxLocalTensor);
226	        }
227	    }
228	    sortDataCopyOutQueue.FreeTensor(outLocal);
229	}
230	
231	__aicore__ inline void MoeV3FullLoad::Init(
232	    GM_ADDR x, GM_ADDR expertIdx, GM_ADDR scale, GM_ADDR offset, GM_ADDR expandedX, GM_ADDR expandedRowIdx,
233	    GM_ADDR expertTokensCountOrCumsum, GM_ADDR expandedScale, const MoeInitRoutingV3TilingData* tilingData,
234	    TPipe* tPipe)
235	{
236	    this->pipe = tPipe;
237	    this->blockIdx = GetBlockIdx();
238	    this->n = tilingData->n;
239	    this->k = tilingData->k;
240	    this->tileLength = Align(tilingData->vbsComputeParamsOp.lastCorePerLoopElements, sizeof(int32_t));
241	    this->sortNum = Ceil(this->tileLength, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
242	    this->totalLength = tilingData->n * tilingData->k;
243	    cols_ = tilingData->cols;
244	    rowIdxType_ = tilingData->rowIdxType;
245	
246	    expertIdxGm.SetGlobalBuffer((__gm__ int32_t*)expertIdx, this->tileLength);
247	
248	    expandedRowIdxGm.SetGlobalBuffer((__gm__ int32_t*)expandedRowIdx, this->tileLength);
249	    expertTokensCountOrCumsumGm.SetGlobalBuffer((__gm__ int64_t*)expertTokensCountOrCumsum, this->tileLength);
250	
251	    inputXGm.SetGlobalBuffer((__gm__ bfloat16_t*)x, this->n * cols_);
252	    smoothGm.SetGlobalBuffer((__gm__ float*)scale, expertNum_ * cols_);
253	    expandedXGm.SetGlobalBuffer((__gm__ int8_t*)expandedX, this->n * cols_ * this->k);
254	    expandedScaleGm.SetGlobalBuffer((__gm__ float*)expandedScale, this->n * this->k);
255	
256	    // key and value
257	    int64_t buffSize = this->sortNum * sizeof(int32_t) * kvFactor;
258	    pipe->InitBuffer(sortDataCopyInQueue, bufferNum, buffSize);
259	    pipe->InitBuffer(sortDataCopyOutQueue, bufferNum, buffSize);
260	    pipe->InitBuffer(tempBuffer, buffSize);
261	    pipe->InitBuffer(sortedBuffer, buffSize);
262	    pipe->InitBuffer(expertTokensCountOrCumsumOutQueue, bufferNum, Align(expertNum_ * kvFactor, sizeof(int32_t)));
263	
264	    pipe->InitBuffer(smoothInQueue, bufferNum, AlignBytes(cols_, sizeof(float)));
265	    pipe->InitBuffer(inputXInQueue, bufferNum, AlignBytes(cols_, sizeof(bfloat16_t)));
266	    pipe->InitBuffer(inputXOutQueue, bufferNum, AlignBytes(cols_, sizeof(int8_t)));
267	    pipe->InitBuffer(quantTempBuffer, AlignBytes(cols_, sizeof(float)));
268	    pipe->InitBuffer(scaleOutQueue, bufferNum, AlignBytes(1, sizeof(float)));
269	    pipe->InitBuffer(rowIdxOutQueue, bufferNum, AlignBytes(this->totalLength, sizeof(int32_t)));
270	}
271	
272	__aicore__ inline void MoeV3FullLoad::Process()
273	{
274	    if (this->blockIdx < GetBlockNum()) {
275	        CopyIn();
276	        SortCompute();
277	        ExpertCountCompute();
278	        CopyOutDynamicQuant();
279	    }
280	}
281	} // namespace MoeInitRoutingV3
282	#endif // MOE_V3_FULL_LOAD_H

